head.b:skin:
    /* SUSHI ELITE v170.0 - PHASE 7 UPDATE */
    :root {
        --primary: #ce1212; --primary-dark: #a00d0d;
        --secondary: #2d3436; --accent: #ffc107;
        --bg-body: #f8f9fa; --bg-card: #ffffff;
        --text-main: #1d1d1f; --text-muted: #636e72;
        --border-color: rgba(0,0,0,0.08);
        --radius-xl: 16px;
        --shadow-card: 0 4px 12px rgba(0,0,0,0.05);
        --z-marquee: 1040; --z-navbar: 1030; --z-floating: 1080;
        --blue-btn: #0d6efd;
    }

    [data-theme='dark'] { --bg-body: #121212; --bg-card: #1e1e1e; --text-main: #f5f5f7; --text-muted: #b2bec3; --border-color: rgba(255,255,255,0.1); }

    /* RTL Support */
    html[dir="rtl"] body { font-family: "Cairo", sans-serif; }
    html[dir="rtl"] .product-title { text-align: right; }
    html[dir="rtl"] .cart-notification { left: 50%; transform: translateX(-50%) translateY(100px); }
    html[dir="rtl"] .cart-notification.active { transform: translateX(-50%) translateY(0); }
    html[dir="rtl"] .cn-link { margin-left: 0; margin-right: auto; }
    html[dir="rtl"] .bi-arrow-right::before { content: "\f12f"; }
    html[dir="rtl"] .header .badge.rounded-pill { right: auto !important; left: 0 !important; transform: translate(-30%, -30%) !important; }

    /* LAYOUT & SPACING */
    body { font-family: "Inter", sans-serif; background: var(--bg-body); color: var(--text-main); padding-top: 0px; padding-bottom: 90px; overflow-x: hidden; transition: background 0.3s; }

    /* HEADER ELEMENTS */
    /* HEADER ELEMENTS - GLASS EFFECT */
    #main-header { 
        top: 0px !important; 
        transition: top 0.3s;

        /* White background with 85% Opacity (0.85) */
        background: rgba(255, 255, 255, 0.85);

        /* Blurs the content behind the header (Frosted Glass) */
        backdrop-filter: blur(12px);
        -webkit-backdrop-filter: blur(12px); /* For Safari */

        /* Optional: Subtle border to separate header from content */
        border-bottom: 1px solid rgba(0,0,0,0.05);
    }

    /* DARK MODE SUPPORT */
    [data-theme='dark'] #main-header {
        /* Dark background with 85% Opacity */
        background: rgba(18, 18, 18, 0.85); 
        border-bottom: 1px solid rgba(255,255,255,0.05);
    }

    /* HIDE PROMO BAR */
    .promo-bar { display: none !important; }

    /* ADJUST BODY PADDING */
    body { padding-top: 80px; } /* Increased to prevent content hiding behind header */

    /* Fix Mobile Header Text Size */
    @media (max-width: 768px) {
         #main-header h1 { font-size: 1.5rem !important; }
         .profile-modern-header { padding: 10px 15px !important; }
    }
    .header .btn.position-relative { overflow: visible !important; }
    .header .badge.rounded-pill { top: 0 !important; right: 0 !important; left: auto !important; transform: translate(30%, -30%) !important; border: 2px solid #fff; }

    /* CATALOG */
    .product-card { background: var(--bg-card); border-radius: var(--radius-xl); overflow: hidden; height: 100%; transition: transform 0.2s; border: 1px solid var(--border-color); box-shadow: var(--shadow-card); position: relative; }
    .product-card:hover { transform: translateY(-4px); }
    .product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4/3; overflow: hidden; background: #f1f2f6; cursor: pointer; }
    .product-img { width: 100%; height: 100%; object-fit: cover; transition: opacity 0.3s ease; }
    .product-img.alt { opacity: 0; position: absolute; top:0; left:0; } .product-card:hover .product-img.alt { opacity: 1; }
    .product-title { font-size: 0.95rem; font-weight: 700; line-height: 1.3; margin-bottom: 5px; color: var(--text-main); white-space: normal; overflow: visible; }
    @media (max-width: 768px) { .product-title { font-size: 0.8rem; } }

    /* CART & SUMMARY */
    .cart-item-card { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 12px; padding: 15px; margin-bottom: 15px; display: flex; align-items: flex-start; gap: 15px; transition: 0.2s; position: relative; }
    .cart-item-img { width: 90px !important; height: 90px !important; min-width: 90px !important; object-fit: cover; border-radius: 8px; background: #f0f0f0; flex-shrink: 0; }
    .qty-selector { display: flex; align-items: center; border: 1px solid var(--border-color); border-radius: 50px; overflow: hidden; width: fit-content; background: #fff; }
    .qty-btn { border: none; background: #fff; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; font-weight: bold; color: var(--text-muted); cursor: pointer; }
    .action-icon { cursor: pointer; font-size: 1.1rem; padding: 5px; transition: 0.2s; }
    .summary-card { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 25px; position: sticky; top: 120px; }
    .summary-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; font-size: 0.95rem; color: var(--text-muted); border-bottom: 1px dashed var(--border-color); padding-bottom: 8px; }
    .summary-total { border-top: 2px solid var(--border-color); padding-top: 15px; margin-top: 15px; display: flex; justify-content: space-between; align-items: center; font-weight: 800; font-size: 1.3rem; color: var(--text-main); }

    /* ORDERS & PROFILE - MOBILE OPTIMIZED */
    .profile-modern-header { background: var(--bg-card); padding: 15px; border-radius: 16px; box-shadow: var(--shadow-card); margin-bottom: 20px; border: 1px solid var(--border-color); display: flex; align-items: center; gap: 12px; }
    .avatar-wrapper { flex-shrink: 0; position: relative; }
    .avatar-img { width: 50px; height: 50px; border-radius: 50%; object-fit: cover; border: 2px solid #fff; }
    .profile-info { flex-grow: 1; min-width: 0; line-height: 1.1; }
    #user-name-display { font-size: 1rem; margin: 0; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    .profile-info .sub-link { font-size: 0.65rem !important; text-transform: uppercase; letter-spacing: 0.5px; display: block; margin-top: 3px; color: var(--text-muted); }
    .profile-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; flex-shrink: 0; }
    .profile-actions .sub-link { font-size: 0.7rem; font-weight: 600; cursor: pointer; padding: 2px 10px; border-radius: 20px; background: rgba(0,0,0,0.04); transition: 0.2s; text-decoration: none; color: var(--text-main); }
    .profile-actions .sub-link:hover { background: rgba(0,0,0,0.08); }
    .profile-actions .text-danger { color: #dc3545 !important; background: rgba(220, 53, 69, 0.1); }

    /* Orders & Details Cards */
    .order-card-modern { background: var(--bg-card); border: 1px solid var(--border-color); border-radius: 16px; padding: 20px; margin-bottom: 15px; transition: 0.2s; }
    .order-thumbs { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 10px; }
    .order-thumb-img { width: 60px !important; height: 60px !important; min-width: 60px !important; object-fit: cover; border-radius: 8px; background: #f8f9fa; border: 1px solid var(--border-color); flex-shrink: 0; }
    .order-detail-row { display: flex; align-items: center; gap: 15px; margin-bottom: 10px; padding-bottom: 10px; border-bottom: 1px solid var(--border-color); }
    .od-img { width: 60px !important; height: 60px !important; min-width: 60px !important; object-fit: cover; border-radius: 8px; background: #f0f0f0; }

    /* ADDRESS CARD */
    .address-card { border:1px solid var(--border-color); border-radius: 12px; padding: 20px; height: 100%; transition: 0.2s; background: var(--bg-card); position: relative; cursor: pointer; }
    .address-card:hover { border-color: var(--primary); background: var(--bg-body); }
    .address-tag { position: absolute; top: 15px; right: 15px; background: #e7f1ff; color: var(--blue-btn); font-size: 0.7rem; font-weight: 700; padding: 4px 10px; border-radius: 20px; html[dir="rtl"] & { right: auto; left: 15px; } }

    /* BADGES */
    .badge-float { position: absolute; top: 10px; right: 10px; z-index: 10; padding: 4px 10px; border-radius: 4px; font-weight: 700; font-size: 0.65rem; color: #fff; text-transform: uppercase; box-shadow: 0 2px 5px rgba(0,0,0,0.2); html[dir="rtl"] & { right: auto; left: 10px; } }
    .badge-hot { background: #ff4757; } 
    .badge-low { background: #ffa502; animation: pulse 2s infinite; } 
    .badge-out { background: #2f3542; } 

    /* NOTIFICATION & UTILS */
    .cart-notification { position: fixed; bottom: 30px; left: 50%; transform: translateX(-50%) translateY(100px); background: #1d1d1f; color: #fff; padding: 12px 20px; border-radius: 50px; z-index: 1100; display: flex; gap: 20px; align-items: center; box-shadow: 0 10px 40px rgba(0,0,0,0.3); transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275), opacity 0.3s; pointer-events: none; width: 90%; max-width: 380px; }
    .cart-notification.active { transform: translateX(-50%) translateY(0); opacity: 1; pointer-events: all; }
    .cn-count { background: var(--primary); color: #fff; width: 24px; height: 24px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; font-weight: bold; }
    .cn-link { color: #fff; text-decoration: none; font-weight: 700; font-size: 0.9rem; margin-left: auto; cursor: pointer; html[dir="rtl"] & { margin-right: auto; margin-left: auto; } }

    .nav-pills .nav-link { border-radius: 50px; color: var(--text-muted); font-weight: 600; padding: 8px 16px; transition: 0.2s; font-size: 0.85rem; margin-right: 5px; }
    .nav-pills .nav-link.active { background-color: var(--primary); color: #fff; box-shadow: 0 4px 10px rgba(206, 18, 18, 0.3); }
    .wish-btn-card { position: absolute; bottom: 10px; left: 10px; z-index: 10; width: 35px; height: 35px; background: var(--bg-card); border-radius: 50%; border: 1px solid var(--border-color); display: flex; align-items: center; justify-content: center; color: #ccc; transition: 0.2s; cursor: pointer; box-shadow: 0 2px 8px rgba(0,0,0,0.1); html[dir="rtl"] & { left: auto; right: 10px; } }
    .wish-btn-card.active { color: var(--primary); border-color: var(--primary); background: #fff5f5; }
    .module-section { display: none; opacity: 0; transition: opacity 0.3s; }
    .module-section.active { display: block; opacity: 1; }
    .settings-item { padding: 15px; border-bottom: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; cursor: pointer; }

    #global-loader { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: var(--bg-body); z-index: 9999; display: flex; flex-direction: column; justify-content: center; align-items: center; transition: opacity 0.5s; }
    .toast-container { position: fixed; bottom: 90px; left: 50%; transform: translateX(-50%); z-index: 1060; width: 90%; max-width: 350px; pointer-events: none; }
    .custom-toast { background: var(--bg-card); color: var(--text-main); border-left: 4px solid var(--primary); box-shadow: 0 10px 30px rgba(0,0,0,0.15); border-radius: 12px; padding: 15px; margin-bottom: 10px; pointer-events: auto; display: flex; align-items: center; justify-content: space-between; animation: slideUp 0.3s; html[dir="rtl"] & { border-left: none; border-right: 4px solid var(--primary); } }
    @keyframes slideUp { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
    @keyframes loading { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
    .skeleton { background: linear-gradient(90deg, var(--bg-card) 25%, var(--border-color) 50%, var(--bg-card) 75%); background-size: 200% 100%; animation: loading 1.5s infinite; border-radius: 4px; }
    .delivery-bar-bg { height: 6px; background: #e9ecef; border-radius: 10px; overflow: hidden; margin-top: 5px; }
    .delivery-bar-fill { height: 100%; background: #198754; width: 0%; transition: width 0.5s ease; }
    .filter-scroll { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 10px; scrollbar-width: none; }
    .filter-scroll::-webkit-scrollbar { display: none; }
    /* FIXED FILTER CHIPS */
    .filter-chip { 
        display: inline-flex !important; /* Force flex layout */
        align-items: center;
        gap: 8px;
        white-space: nowrap; 
        padding: 6px 16px; 
        border-radius: 20px; 
        background: var(--bg-card); 
        border: 1px solid var(--border-color); 
        color: var(--text-muted); 
        font-weight: 600; 
        cursor: pointer; 
        transition: 0.2s; 
        font-size: 0.85rem; 
        height: 38px; /* Force fixed height */
    }
    .filter-chip:hover { 
        transform: translateY(-2px); 
        border-color: var(--primary);
    }
    .filter-chip.active { 
        background: var(--primary); 
        color: #fff; 
        border-color: var(--primary); 
    }

    /* FORCE ICON SIZE */
    .filter-chip img, .chip-icon { 
        width: 20px !important; 
        height: 20px !important; 
        min-width: 20px !important;
        object-fit: contain; 
        display: block;
    }

    .filter-chip.active img { filter: brightness(0) invert(1); }
    .flying-img { position: fixed; z-index: 9999; pointer-events: none; transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; opacity: 0.8; }
    .btn-pill-group .btn-outline-secondary { border-radius: 50px; font-size: 0.75rem; padding: 6px 14px; margin-right: 6px; border-color: var(--border-color); color: var(--text-main); }
    .btn-pill-group .btn-check:checked + .btn-outline-secondary { background-color: var(--secondary); color: #fff; border-color: var(--secondary); }
    .status-pill-processing { background: #fff3cd; color: #856404; padding: 4px 12px; border-radius: 50px; font-size: 0.8rem; font-weight: 700; }
    .status-pill-completed { background: #d1e7dd; color: #0f5132; padding: 4px 12px; border-radius: 50px; font-size: 0.8rem; font-weight: 700; }
    .qv-img-container { height: 250px; width: 100%; background: #f8f9fa; display: flex; align-items: center; justify-content: center; border-radius: 8px; overflow: hidden; margin-bottom: 15px; }
    .qv-img { max-width: 100%; max-height: 100%; object-fit: contain; }

    /* MARQUEE & BANNER */
    .promo-bar { background: #2d3436; color: #fff; height: 32px; line-height: 32px; position: fixed; top: 0; left: 0; width: 100%; z-index: 1040; overflow: hidden; font-size: 0.8rem; font-weight: 600; }
    .promo-content { display: inline-block; white-space: nowrap; animation: marquee 20s linear infinite; padding-left: 100%; html[dir="rtl"] & { animation: marqueeRtl 20s linear infinite; padding-right: 100%; padding-left: 0; } }
    @keyframes marquee { 0% { transform: translate(0, 0); } 100% { transform: translate(-100%, 0); } }
    @keyframes marqueeRtl { 0% { transform: translate(0, 0); } 100% { transform: translate(100%, 0); } }
    #store-closed-banner { top: 32px !important; }

    /* --- MOBILE OPTIMIZATIONS (Max Width 768px) --- */
    @media (max-width: 768px) {
        .profile-modern-header { padding: 8px 12px !important; gap: 10px !important; align-items: flex-start !important; }
        .avatar-img { width: 40px !important; height: 40px !important; }
        .profile-info { padding-top: 2px; }
        #user-name-display { font-size: 0.9rem !important; max-width: 140px; }
        .profile-info .sub-link { font-size: 0.6rem !important; margin-top: 0 !important; }
        .profile-actions { display: flex !important; flex-direction: column !important; align-items: flex-end !important; gap: 4px !important; margin-left: auto !important; }
        .profile-actions .sub-link { font-size: 0.6rem !important; padding: 2px 8px !important; border-radius: 4px !important; background: #f1f2f6; width: fit-content; text-align: center; display: block; }
        .product-card .p-3 { padding: 8px !important; }
        .product-title { font-size: 0.8rem !important; margin-bottom: 4px !important; line-height: 1.2 !important; height: 2.4em; }
        .product-card .text-primary.fw-bold, .product-card .text-danger.fw-bold { font-size: 0.85rem !important; }
        .product-card s.text-muted { font-size: 0.7rem !important; }
        .cart-item-card { padding: 8px !important; gap: 8px !important; }
        .cart-item-img { width: 60px !important; height: 60px !important; min-width: 60px !important; }
        .cart-item-card h6 { font-size: 0.8rem !important; max-width: 130px; }
        #main-header h1 { font-size: 1.4rem !important; }
        .breadcrumb-bar { font-size: 0.7rem !important; padding: 5px 0 !important; }
    }

    /* --- WELCOME MODAL STYLES --- */
    .welcome-card { border: 2px solid var(--border-color); border-radius: 16px; padding: 15px; cursor: pointer; transition: 0.2s; text-align: center; background: var(--bg-card); }
    .welcome-card:hover { border-color: var(--primary); background: rgba(206, 18, 18, 0.05); }
    .welcome-card.selected { border-color: var(--primary); background: rgba(206, 18, 18, 0.1); position: relative; }
    .welcome-card.selected::after { content: '\F26B'; font-family: 'bootstrap-icons'; position: absolute; top: 10px; right: 10px; color: var(--primary); font-weight: bold; }
    .welcome-flag { width: 40px; height: 40px; object-fit: cover; border-radius: 50%; margin-bottom: 10px; border:1px solid #eee; }

    /* STORE CLOSED / PRE-ORDER MODE */
    body.is-closed #main-header { top: 72px; }
    body.is-closed { padding-top: 150px; }
    .store-banner { height: 40px; line-height: 40px; text-align: center; position: fixed; top: 32px; left: 0; width: 100%; z-index: 1035; background: linear-gradient(45deg, #2d3436, #000); color: #fff; font-size: 0.85rem; font-weight: 600; display: none; box-shadow: 0 4px 10px rgba(0,0,0,0.1); }
    body.is-closed .store-banner { display: block; animation: slideDown 0.4s ease; }
    @keyframes slideDown { from { transform: translateY(-100%); } to { transform: translateY(0); } }

	/* FLOATING STATUS PILL */
.store-status-float {
    position: fixed;
    bottom: 20px;
    left: 20px;
    z-index: 1090; /* High z-index */
    background: #2d3436;
    color: #fff;
    padding: 10px 20px;
    border-radius: 50px;
    box-shadow: 0 10px 30px rgba(0,0,0,0.15);
    font-weight: 700;
    font-size: 0.85rem;
    display: none; /* Hidden by default */
    align-items: center;
    gap: 10px;
    border: 1px solid rgba(255,255,255,0.1);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
}

.store-status-float.active {
    display: flex;
    animation: fadeUp 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.status-dot {
    width: 10px;
    height: 10px;
    background: #ff4757;
    border-radius: 50%;
    box-shadow: 0 0 0 4px rgba(255, 71, 87, 0.2);
    animation: pulseRed 2s infinite;
}

@keyframes fadeUp {
    from { transform: translateY(20px); opacity: 0; }
    to { transform: translateY(0); opacity: 1; }
}

@keyframes pulseRed {
    0% { box-shadow: 0 0 0 0 rgba(255, 71, 87, 0.7); }
    70% { box-shadow: 0 0 0 6px rgba(255, 71, 87, 0); }
    100% { box-shadow: 0 0 0 0 rgba(255, 71, 87, 0); }
}

/* Mobile Tweak: Ensure it doesn't cover bottom nav items if you have them */
@media (max-width: 768px) {
    .store-status-float {
        bottom: 80px; /* Move up slightly on mobile */
        left: 50%;
        transform: translateX(-50%);
        width: auto;
        white-space: nowrap;
    }
    .store-status-float.active {
         /* Override animation for centered element */
         animation: fadeUpCenter 0.4s ease forwards;
    }
    @keyframes fadeUpCenter {
        from { transform: translate(-50%, 20px); opacity: 0; }
        to { transform: translate(-50%, 0); opacity: 1; }
    }
}

@media print {
    body * { visibility: hidden; }
    #print-area, #print-area * { visibility: visible; }
    #print-area {
        position: absolute; left: 0; top: 0; width: 100%; margin: 0; padding: 0;
        font-family: 'Courier New', monospace; font-size: 14px; color: black;
    }
    .ticket-header { text-align: center; border-bottom: 2px dashed #000; padding-bottom: 10px; margin-bottom: 10px; }
    .ticket-row { display: flex; justify-content: space-between; margin-bottom: 5px; }
    .ticket-total { border-top: 2px dashed #000; margin-top: 10px; padding-top: 10px; font-weight: bold; font-size: 18px; text-align: right; }
    .ticket-footer { text-align: center; margin-top: 20px; font-size: 12px; }
}

/* MARKETPLACE AUTO-BOUNCE EVERY 5 SECONDS */
  @keyframes shop-bounce-timed {
      0%, 20%, 50%, 80%, 100% { transform: translateY(0); }
      40% { transform: translateY(-10px); }
      60% { transform: translateY(-5px); }
  }

  .marketplace-btn i {
      display: inline-block !important; /* <--- THIS IS REQUIRED TO MOVE */
      animation: shop-bounce-timed 5s ease-in-out infinite;
      color: var(--primary);
  }
/* Add inside your <style> tag */
.cursor-pointer { cursor: pointer; }
.cursor-pointer:active { transform: scale(0.98); opacity: 0.8; }

/* Add this to your <b:skin> or <style> */
.story-nav-container {
    display: flex;
    gap: 15px;
    overflow-x: auto;
    padding: 10px 5px;
    scrollbar-width: none; /* Hide scrollbar Firefox */
}
.story-nav-container::-webkit-scrollbar { display: none; } /* Hide scrollbar Chrome */

.story-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 70px;
    cursor: pointer;
    transition: transform 0.2s;
}
.story-item:active { transform: scale(0.95); }
.story-item.active .story-ring { border-color: var(--primary); background: #fff5f5; }
.story-item.active .story-label { color: var(--primary); font-weight: 800; }

.story-ring {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    padding: 3px;
    border: 2px solid #eee;
    margin-bottom: 5px;
    background: #fff;
}
.story-img {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
}
.story-label {
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--text-muted);
    white-space: nowrap;
}

body.script:
//
// 1. INJECT CSS STYLES
const style = document.createElement('style');
style.innerHTML = `
  .btn-clicked { transform: scale(0.95); background-color: var(--primary-dark) !important; transition: 0.1s; }
  .img-fade { opacity: 0; transition: opacity 0.5s ease-in-out; }
  .sticky-checkout { position: fixed; bottom: 0; left: 0; width: 100%; background: var(--bg-card); padding: 15px; box-shadow: 0 -5px 20px rgba(0,0,0,0.1); z-index: 1020; border-top: 1px solid var(--border-color); display: flex; justify-content: space-between; align-items: center; animation: slideUp 0.3s ease-out; }
  .related-item { cursor: pointer; transition: 0.2s; border: 1px solid var(--border-color); border-radius: 8px; padding: 8px; display: flex; align-items: center; gap: 10px; }
  .related-item:hover { background: #f8f9fa; border-color: var(--primary); }
  .related-img { width: 50px; height: 50px; object-fit: cover; border-radius: 6px; }
  .wish-btn-card.active i { color: #dc3545 !important; } .wish-btn-card.active { border-color: #dc3545 !important; background: #fff5f5 !important; }
  .star-rating { color: #ffc107; font-size: 0.8rem; margin-bottom:4px; }
  .review-card { background: #f8f9fa; border-radius: 12px; padding: 12px; margin-bottom: 10px; border:1px solid #eee; }
  .points-badge { background: linear-gradient(45deg, #FFD700, #FFA500); color: #000; padding: 4px 10px; border-radius: 20px; font-weight: bold; font-size: 0.7rem; margin-top:5px; display:inline-block; box-shadow: 0 2px 5px rgba(0,0,0,0.1); }
  .timeline { position: relative; padding-left: 20px; border-left: 2px solid #e9ecef; margin: 15px 0 15px 10px; }
  .timeline-item { position: relative; margin-bottom: 15px; }
  .timeline-item::before { content: ''; position: absolute; left: -27px; top: 5px; width: 12px; height: 12px; border-radius: 50%; background: #e9ecef; border: 2px solid #fff; box-shadow: 0 0 0 1px #dee2e6; }
  .timeline-item.active::before { background: #198754; box-shadow: 0 0 0 1px #198754; }
  .timeline-item.active .time-label { color: #198754; font-weight:bold; }
  .extra-item { display: flex; justify-content: space-between; align-items: center; padding: 8px 0; border-bottom: 1px dashed #eee; font-size: 0.9rem; }
  .extra-item:last-child { border-bottom: none; }
  .star-interactive { cursor: pointer; transition: transform 0.2s, color 0.2s; }
  .star-interactive:hover { transform: scale(1.2); }

  /* ADMIN CSS */
  .admin-card { border-left: 4px solid #0d6efd; background: #fff; padding: 15px; margin-bottom: 15px; border-radius: 8px; box-shadow: 0 2px 5px rgba(0,0,0,0.05); }
  .admin-card.completed { border-left-color: #198754; opacity: 0.7; }

  /* INSTALL POPUP */
  .install-toast { position: fixed; bottom: -120px; left: 50%; transform: translateX(-50%); width: 90%; max-width: 400px; background: rgba(255,255,255,0.95); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border-radius: 20px; padding: 15px; box-shadow: 0 20px 50px rgba(0,0,0,0.2); z-index: 9999; display: flex; align-items: center; gap: 15px; transition: bottom 0.6s cubic-bezier(0.19, 1, 0.22, 1); border: 1px solid rgba(255,255,255,0.5); }
  .install-toast.active { bottom: 30px; }
  .install-img { width: 48px; height: 48px; border-radius: 12px; object-fit: cover; box-shadow: 0 4px 10px rgba(0,0,0,0.1); }

  /* THERMAL PRINTER CSS */
  @media print {
    body * { visibility: hidden; }
    #print-area, #print-area * { visibility: visible; }
    #print-area { position: absolute; left: 0; top: 0; width: 100%; color: black; background: white; font-family: 'Courier New', monospace; }
    .print-header { text-align: center; border-bottom: 2px dashed #000; padding-bottom: 10px; margin-bottom: 10px; }
    .print-row { display: flex; justify-content: space-between; margin-bottom: 5px; font-size: 14px; }
    .print-total { border-top: 2px dashed #000; padding-top: 10px; margin-top: 10px; font-weight: bold; font-size: 16px; }
  }
  @media(min-width: 769px) { .sticky-checkout { display: none !important; } }

  /* THERMAL PRINTER CSS */
  @media print {
    body * { visibility: hidden; }
    #print-area, #print-area * { visibility: visible; }
    #print-area {
        position: absolute; left: 0; top: 0; width: 100%; margin: 0; padding: 0;
        font-family: 'Courier New', monospace; font-size: 14px; color: black;
        background: white;
    }
    .ticket-header { text-align: center; border-bottom: 2px dashed #000; padding-bottom: 10px; margin-bottom: 10px; }
    .ticket-body { margin-bottom: 15px; }
    .ticket-row { display: flex; justify-content: space-between; margin-bottom: 5px; }
    .ticket-total { border-top: 2px dashed #000; margin-top: 10px; padding-top: 10px; font-weight: bold; font-size: 18px; text-align: right; }
    .ticket-footer { text-align: center; margin-top: 20px; font-size: 12px; }
  }

  /* STORE CLOSED / PRE-ORDER MODE */
  body.is-closed #main-header { top: 72px; }
  body.is-closed { padding-top: 150px; }
  .store-banner {
      height: 40px; line-height: 40px; text-align: center;
      position: fixed; top: 32px; left: 0; width: 100%; z-index: 1035;
      background: linear-gradient(45deg, #2d3436, #000); color: #fff;
      font-size: 0.85rem; font-weight: 600; display: none;
      box-shadow: 0 4px 10px rgba(0,0,0,0.1);
  }
  body.is-closed .store-banner { display: block; animation: slideDown 0.4s ease; }
  @keyframes slideDown { from { transform: translateY(-100%); } to { transform: translateY(0); } }

  /* FIX RTL CART NOTIFICATION */
  html[dir="rtl"] .cart-notification { left: 50%; transform: translateX(-50%) translateY(100px); }
  html[dir="rtl"] .cart-notification.active { transform: translateX(-50%) translateY(0); }
`;
