    // 3. I18N
    I18n: {
        setLang: (l, reload = true) => { App.State.lang = l; localStorage.setItem('se_lang', l); if(App.State.user) App.API.updateLang(l); if(reload) { App.UI.showReload(); } else { document.documentElement.setAttribute('dir', l === 'ar' ? 'rtl' : 'ltr'); App.UI.updateIcons(); App.I18n.updateDOM(); App.Cart.render(); App.Catalog.renderBatch(true); App.Cart.renderZones(App.Config.zoneData); const bc = document.getElementById('breadcrumbs'); if(bc && (bc.innerHTML.includes("Home") || bc.innerHTML.includes("Accueil") || bc.innerHTML.includes("الرئيسية"))) { App.Router.go(App.State.currentView || 'home'); } } },
        t: (key) => { if(!key) return ""; let dict = App.State.translations[key]; if (!dict) { const foundKey = Object.keys(App.State.translations).find(k => k.toLowerCase() === key.toLowerCase()); if (foundKey) dict = App.State.translations[foundKey]; } if(dict) { const val = dict[App.State.lang]; if(val && (val.includes("#NAME?") || val.includes("#ERROR"))) return dict['en']; return val || dict['en']; } return key; },
        updateDOM: () => { 
            document.querySelectorAll('[data-i18n]').forEach(el => { const key = el.getAttribute('data-i18n'); if(key) el.innerText = App.I18n.t(key); }); 
            const phMap = {'login-phone': 'ph_phone', 'login-pass': 'ph_password', 'reg-name': 'ph_name', 'reg-phone': 'ph_phone', 'reg-pass': 'ph_password', 'addr-name': 'ph_name', 'addr-street': 'ph_address', 'addr-apt': 'ph_address', 'addr-city': 'lbl_city', 'addr-zip': 'lbl_zip', 'chk-name': 'ph_name', 'chk-phone': 'ph_phone', 'chk-address': 'ph_address', 'order-note': 'ph_notes', 'setting-name': 'ph_name', 'setting-email': 'lbl_email', 'res-name': 'ph_name', 'res-phone': 'ph_phone', 'review-comment': 'ph_review', 'admin-pw': 'ph_pin', 'coupon-code': 'lbl_extras', 'res-date': 'lbl_date', 'driver-pin': 'ph_driver_pin'}; 

            Object.keys(phMap).forEach(id => { const el = document.getElementById(id); if(el) el.placeholder = App.I18n.t(phMap[id]) || el.placeholder; }); 

            // Generic Placeholder Translator
            document.querySelectorAll('[data-i18n-ph]').forEach(el => {
                const key = el.getAttribute('data-i18n-ph');
                if(key) el.placeholder = App.I18n.t(key);
            });

            const search = document.getElementById('search-input'); if(search) search.placeholder = App.I18n.t('search_ph') || "Search..."; const typeSel = document.getElementById('addr-type'); if(typeSel) { if(typeSel.options[0]) typeSel.options[0].text = App.I18n.t('lbl_home'); if(typeSel.options[1]) typeSel.options[1].text = App.I18n.t('lbl_office'); } const countryInput = document.getElementById('addr-country'); if(countryInput) { const current = countryInput.value; if (!current || current.includes('Morocco') || current.includes('Maroc')) countryInput.value = App.I18n.t('val_morocco'); } },
        fetch: () => { fetch(API_URL + '?action=getTranslations').then(r=>r.json()).then(res=>{ if(res.status==='success') { App.State.translations = {...App.State.translations, ...res.data}; App.I18n.updateDOM(); App.Cart.render(); } }); }
    }, 

    // 4. UTILS
    Utils: {
        fmt: (price) => { 
            // SAFETY CHECK: Ensure price is a number
            let p = parseFloat(price);
            if (isNaN(p)) p = 0; 

            const c = App.State.currency; 
            const l = App.State.lang; 
            const val = (p * (App.State.exchange[c] || 1)).toFixed(2); 

            if (c === 'MAD') return l === 'ar' ? `${val} د.م.` : `${val} DH`; 
            if (c === 'EUR') return `€${val}`; 
            if (c === 'USD') return `$${val}`; 
            return `${val} ${c}`; 
        },
        save: (key, val) => localStorage.setItem(key, JSON.stringify(val)),
        load: (key) => { try { return JSON.parse(localStorage.getItem(key)) } catch(e) { return null } },
        el: (id) => document.getElementById(id) || { classList: { remove:()=>{}, add:()=>{} }, innerText: '', innerHTML: '', value: '' },
        checkStock: (i) => { if(i.stock === 0) return { disabled: true, badge: `<span class="badge-float badge-out">${App.I18n.t('lbl_sold_out')}</span>` }; if(i.stock < 5) return { disabled: false, badge: `<span class="badge-float badge-low">${App.I18n.t('lbl_low_stock')}</span>` }; if(String(i.tags).includes('on_sale')) return { disabled: false, badge: `<span class="badge-float bg-success">${App.I18n.t('lbl_on_sale')}</span>` }; if(String(i.tags).includes('hot')) return { disabled: false, badge: `<span class="badge-float badge-hot">${App.I18n.t('lbl_hot')}</span>` }; return { disabled: false, badge: '' }; },
        getLocalizedText: (obj) => { if(typeof obj === 'string') return obj; if(!obj) return ""; return obj[App.State.lang] || obj['en'] || ""; },
        isValidPhone: (p) => { var clean = String(p).replace(/[\s\-\(\)]/g, ''); return /^(?:(?:\+|00)212|0)[67]\d{8}$/.test(clean); },
        optimizeImg: (url) => { if(!url) return IMG_FALLBACK; if(url.includes('blogger.googleusercontent.com')) return url.replace(/\/s\d+\//, '/w400-h400-c/'); return url; },
        debounce: (func, wait) => { let timeout; return function(...args) { const context = this; clearTimeout(timeout); timeout = setTimeout(() => func.apply(context, args), wait); }; }
    }, 

    // 5. CATALOG
    // 5. CATALOG (UPGRADED: FUZZY SEARCH & PERFORMANCE)
    Catalog: {
        searchDebounced: null,
        fuse: null, 

        initFuse: () => {
            if(!App.State.catalog || App.State.catalog.length === 0 || typeof Fuse === 'undefined') return;
            const options = {
                includeScore: true, threshold: 0.4, ignoreLocation: true,
                keys: [{name:'title.en',weight:0.6}, {name:'title.fr',weight:0.6}, {name:'title.ar',weight:0.6}, {name:'tags',weight:0.3}, {name:'category',weight:0.2}]
            };
            App.Catalog.fuse = new Fuse(App.State.catalog, options);
        },

        search: (q) => { if(App.Catalog.searchDebounced) App.Catalog.searchDebounced(q); },

        _searchImpl: (q) => { 
            App.State.searchTerm = q; 
            App.UI.transition(() => App.Catalog.renderBatch(true)); 
        },

        renderFilters: () => {
            const c = document.getElementById('category-filters');
            if(!c) return;

            // Define Icons
            const catImages = {
                'All': 'https://cdn-icons-png.flaticon.com/512/3565/3565418.png',
                'Sushi': 'https://cdn-icons-png.flaticon.com/512/2252/2252076.png',
                'Taco': 'https://cdn-icons-png.flaticon.com/512/4474/4474828.png',
                'Box': 'https://cdn-icons-png.flaticon.com/512/6978/6978255.png',
                'Mini Box': 'https://cdn-icons-png.flaticon.com/512/6030/6030105.png',
                'Appetizers': 'https://cdn-icons-png.flaticon.com/512/1046/1046784.png',
                'Drinks': 'https://cdn-icons-png.flaticon.com/512/2405/2405597.png'
            };
            const defaultIcon = 'https://cdn-icons-png.flaticon.com/512/706/706164.png'; 

            const cats = ['All', ...new Set(App.State.catalog.map(i => i.category))];

            // Ensure container has horizontal scroll
            c.className = 'filter-scroll d-flex gap-2'; 

            c.innerHTML = cats.map(cat => {
                const key = 'cat_' + cat.toLowerCase().replace(/\s+/g, '_');
                const trans = App.I18n.t(key);
                const label = (trans && trans !== key) ? trans : cat;
                const activeClass = (cat === App.State.activeCat) ? 'active' : '';
                const iconSrc = catImages[cat] || defaultIcon;

                // RENDER AS COMPACT PILL
                return `
                <div class="filter-chip ${activeClass}" onclick="App.Catalog.setCat('${cat}', this)">
                    <img src="${iconSrc}" class="chip-icon" loading="lazy">
                    <span>${label}</span>
                </div>
                `;
            }).join('');
        },

        setCat: (cat, el) => { 
            App.State.activeCat = cat; 
            document.querySelectorAll('.filter-chip').forEach(e => e.classList.remove('active')); 
            el.classList.add('active'); 
            document.getElementById('search-input').value = '';
            App.State.searchTerm = '';
            App.UI.transition(() => App.Catalog.renderBatch(true)); 
        },

        renderBatch: (reset=false) => { 
            const grid = document.getElementById('product-grid-root'); 
            if(!grid) return; 

            if(reset) { grid.innerHTML = ''; App.State.visibleCount = 0; } 

            // Initialize Fuse if needed
            if (!App.Catalog.fuse && App.State.catalog.length > 0) { App.Catalog.initFuse(); }

            let filteredData = App.State.catalog;

            // Search Logic
            if(App.State.searchTerm && App.State.searchTerm.trim() !== '') {
                if(App.Catalog.fuse) {
                    const results = App.Catalog.fuse.search(App.State.searchTerm);
                    filteredData = results.map(r => r.item);
                } else {
                    const term = App.State.searchTerm.toLowerCase();
                    filteredData = filteredData.filter(i => (Object.values(i.title).join(' ') + " " + i.tags).toLowerCase().includes(term));
                }
            }

            // Category Logic
            filteredData = filteredData.filter(i => (App.State.activeCat === 'All' || i.category === App.State.activeCat)); 

            // Pagination
            const batch = filteredData.slice(App.State.visibleCount, App.State.visibleCount + App.State.batchSize); 

            if(batch.length === 0 && reset) {
                grid.innerHTML = `<div class="col-12 text-center py-5 text-muted">${App.I18n.t('catalog_empty')}</div>`; 
            } else {
                const html = batch.map(i => App.UI.renderCard(i)).join('');
                grid.insertAdjacentHTML('beforeend', html);
            }
            App.State.visibleCount += App.State.batchSize; 
        },

        renderRecent: () => {
            const container = document.getElementById('recent-grid');
            if(!container) return;
            const recentIds = App.State.recent.slice(0, 4);
            if(recentIds.length === 0) {
                container.innerHTML = `<div class="col-12 text-center text-muted small">${App.I18n.t('lbl_no_recent')}</div>`;
                return;
            }
            container.innerHTML = recentIds.map(id => {
                const p = App.State.catalog.find(x => String(x.id) === String(id));
                return p ? App.UI.renderCard(p, true) : ''; 
            }).join('');
        }
    },

    UI: {
        toast: (msg, type='info') => { const c = document.getElementById('toast-container'); const t = document.createElement('div'); t.className = `custom-toast border-${type}`; t.innerHTML = `<span>${msg}</span><button type="button" class="btn-close btn-close-sm" onclick="this.parentElement.remove()"></button>`; c.appendChild(t); setTimeout(() => t.remove(), 3000); },
        confirm: (title, msg, callback) => { App.Utils.el('conf-title').innerText = title; App.Utils.el('conf-msg').innerText = msg; const btn = document.getElementById('conf-btn'); const modal = new bootstrap.Modal(document.getElementById('confirmModal')); const newBtn = btn.cloneNode(true); btn.parentNode.replaceChild(newBtn, btn); newBtn.innerText = App.I18n.t('btn_yes'); newBtn.onclick = () => { callback(); modal.hide(); }; modal.show(); },
        openReviewModal: (pid) => { const p = App.State.catalog.find(x => String(x.id) === String(pid)); if(!p) return; App.State.tempReviewPid = pid; App.State.tempRating = 0; document.getElementById('review-comment').value = ''; document.getElementById('review-prod-name').innerText = App.Utils.getLocalizedText(p.title); App.UI.setStar(0); new bootstrap.Modal(document.getElementById('reviewModal')).show(); },
        setStar: (n) => { App.State.tempRating = n; for(let i=1; i<=5; i++) { const s = document.getElementById('star-'+i); if(i <= n) { s.classList.remove('bi-star', 'text-muted'); s.classList.add('bi-star-fill', 'text-warning'); } else { s.classList.remove('bi-star-fill', 'text-warning'); s.classList.add('bi-star', 'text-muted'); } } },
        setCurrency: (newCurr) => { App.State.lastCurrencyChange = Date.now(); App.State.currency = newCurr; localStorage.setItem('se_curr', newCurr); if(App.State.user) App.API.push('pref'); App.UI.showReload(); },
        selectWelcomeOption: (type, val) => { if(type === 'lang') { App.State.tempLang = val; ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l)?.classList.remove('selected')); document.getElementById('wel-lang-'+val)?.classList.add('selected'); const btn = document.getElementById('btn-welcome-start'); if(btn && App.State.translations['btn_start_ordering']) { btn.innerText = App.State.translations['btn_start_ordering'][val]; } } else { App.State.tempCurr = val; ['MAD','EUR','USD'].forEach(c => document.getElementById('wel-curr-'+c)?.classList.remove('selected')); document.getElementById('wel-curr-'+val)?.classList.add('selected'); } },
        finishWelcome: () => { const l = App.State.tempLang; const c = App.State.tempCurr; localStorage.setItem('se_setup_done', 'true'); localStorage.setItem('se_lang', l); localStorage.setItem('se_curr', c); location.reload(); },
        updateIcons: () => { const l = App.State.lang; const flagBtn = document.getElementById('header-lang-icon'); if(flagBtn && App.State.flags[l]) flagBtn.src = App.State.flags[l]; const setLangBtn = document.getElementById('setting-lang-icon'); if(setLangBtn && App.State.flags[l]) setLangBtn.src = App.State.flags[l]; const c = App.State.currency; const setCurrDisplay = document.getElementById('setting-curr-display'); if(setCurrDisplay) { if (c === 'MAD') setCurrDisplay.innerText = (l === 'ar') ? "د.م." : "MAD"; else if (c === 'EUR') setCurrDisplay.innerText = "EUR"; else setCurrDisplay.innerText = "USD"; } },
        toggleTheme: () => { const body = document.body; const isDark = body.getAttribute('data-theme') === 'dark'; body.setAttribute('data-theme', isDark ? 'light' : 'dark'); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = !isDark; localStorage.setItem('se_theme', !isDark ? 'dark' : 'light'); },

        // --- NEW: VISUAL LOADER (NO RELOAD) ---
        showLoader: () => { 
            let l = document.getElementById('global-loader'); 
            if(!l) return;
            l.innerHTML = `<div class='spinner-border text-primary' role='status' style='width:3rem; height:3rem; border-width:4px;'></div><div class='mt-2 fw-bold text-muted'>${App.I18n.t('msg_updating')}</div>`; 
            l.style.display = 'flex'; 
            l.style.opacity = '1'; 
        },

        // --- EXISTING: HARD RELOAD (Only for Language/Currency Change) ---
        showReload: () => { 
            let l = document.getElementById('global-loader'); 
            if(!l) return; 
            l.innerHTML = `<div class='spinner-border text-primary' role='status' style='width:3rem; height:3rem; border-width:4px;'></div><div class='mt-2 fw-bold text-muted'>${App.I18n.t('msg_updating')}</div>`; 
            l.style.display = 'flex'; 
            l.style.opacity = '1'; 
            setTimeout(() => location.reload(), 500); 
        },

        hideLoader: () => { const l = document.getElementById('global-loader'); if(l) { l.style.opacity = '0'; setTimeout(() => l.remove(), 500); } },

        flyToCart: (imgEl) => { if(!imgEl) return; const cartBtn = document.getElementById('nav-cart-btn'); if(!cartBtn) return; const fly = imgEl.cloneNode(); const rect = imgEl.getBoundingClientRect(); fly.classList.add('flying-img'); fly.style.left = rect.left + 'px'; fly.style.top = rect.top + 'px'; fly.style.width = rect.width + 'px'; fly.style.height = rect.height + 'px'; document.body.appendChild(fly); const cartRect = cartBtn.getBoundingClientRect(); setTimeout(() => { fly.style.left = (cartRect.left + 10) + 'px'; fly.style.top = (cartRect.top + 10) + 'px'; fly.style.width = '20px'; fly.style.height = '20px'; fly.style.opacity = '0'; }, 50); setTimeout(() => fly.remove(), 850); },
        updateHearts: (id, isActive) => { document.querySelectorAll(`.wish-btn-card[data-id="${id}"]`).forEach(b => { if(isActive) { b.classList.add('active'); b.innerHTML = '<i class="bi bi-heart-fill text-danger"></i>'; } else { b.classList.remove('active'); b.innerHTML = '<i class="bi bi-heart"></i>'; } }); },
        transition: (cb) => { const grid = document.getElementById('product-grid-root'); if(grid) grid.innerHTML = Array(4).fill('<div class="col-6 col-md-3"><div class="skeleton" style="height:250px"></div></div>').join(''); setTimeout(() => { if(cb) cb(); }, 300); },
        showCartNotification: () => { const n = document.getElementById('cart-notification'); const c = document.getElementById('cn-count'); if(n && c) { c.innerText = App.State.cart.reduce((a,b)=>a+b.qty, 0); n.classList.add('active'); if(App.State.notifyTimeout) clearTimeout(App.State.notifyTimeout); App.State.notifyTimeout = setTimeout(() => { n.classList.remove('active'); }, 5000); } },

        renderCard: (i, isGrid=true) => { const stock = App.Utils.checkStock(i); const isWish = App.State.wishlist.includes(String(i.id)); const heartClass = isWish ? 'active' : ''; const heartIcon = isWish ? 'bi-heart-fill text-danger' : 'bi-heart'; const colClass = isGrid ? 'col-6 col-md-4 col-lg-3' : 'col-6 col-md-3'; const displayTitle = App.Utils.getLocalizedText(i.title); const safeId = String(i.id).replace(/'/g, "\\'"); let priceHtml = `<span class="text-primary fw-bold">${App.Utils.fmt(i.price_MAD)}</span>`; if(i.old_price_MAD > i.price_MAD) priceHtml = `<div class="d-flex align-items-center gap-2"><s class="text-muted small">${App.Utils.fmt(i.old_price_MAD)}</s> <span class="text-danger fw-bold">${App.Utils.fmt(i.price_MAD)}</span></div>`; 
        const optImg = App.Utils.optimizeImg(i.image || IMG_FALLBACK); 
        return `<div class="${colClass}"><div class="product-card h-100">${stock.badge}<div class="product-img-wrapper" onclick="App.QuickView.open('${safeId}')"><img src="${optImg}" class="product-img img-fade" onload="this.style.opacity=1" loading="lazy" /><button class="wish-btn-card ${heartClass}" data-id="${safeId}" onclick="event.stopPropagation(); event.preventDefault(); App.Wishlist.toggle('${safeId}'); return false;" type="button"><i class="bi ${heartIcon}"></i></button></div><div class="p-3"><div class="star-rating"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i> <span class="text-muted small">(4.5)</span></div><h6 class="product-title">${displayTitle}</h6><div class="d-flex justify-content-between align-items-center">${priceHtml}<button class="btn btn-sm btn-dark rounded-circle" ${stock.disabled ? 'disabled="disabled"' : ''} onclick="event.stopPropagation(); event.preventDefault(); App.Cart.add('${safeId}', this); return false;" type="button"><i class="bi bi-plus"></i></button></div></div></div></div>`; },

        renderQuickView: (p) => { 
            const stock = App.Utils.checkStock(p); const displayTitle = App.Utils.getLocalizedText(p.title);
            let rawDesc = App.Utils.getLocalizedText(p.desc); const cleanDesc = rawDesc.replace(/<[^>]*>?/gm, ''); 
            const safeId = String(p.id).replace(/'/g, "\\'");
            let priceHtml = `<div class="h3 text-primary fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div>`;
            if(p.old_price_MAD > p.price_MAD) priceHtml = `<div class="d-flex align-items-baseline gap-2"><s class="text-muted h5 m-0" id="qv-old-price-display">${App.Utils.fmt(p.old_price_MAD)}</s> <div class="h3 text-danger fw-bold m-0" id="qv-price-display">${App.Utils.fmt(p.price_MAD)}</div></div>`;
            let relatedHtml = ''; const related = App.State.catalog.filter(x => x.category === p.category && x.id !== p.id).slice(0, 2); 
            if(related.length > 0) { relatedHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3 small text-muted" data-i18n="lbl_related">${App.I18n.t('lbl_related')}</h6><div class="d-flex gap-2">${related.map(r => `<div class="related-item flex-fill" onclick="App.QuickView.open('${String(r.id).replace(/'/g, "\\'")}')"><img src="${App.Utils.optimizeImg(r.image || IMG_FALLBACK)}" class="related-img"/><div style="min-width:0"><div class="small fw-bold text-truncate">${App.Utils.getLocalizedText(r.title)}</div><div class="small text-primary fw-bold">${App.Utils.fmt(r.price_MAD)}</div></div></div>`).join('')}</div></div>`; } 
            let extrasHtml = ''; if(p.extras && p.extras.length > 0) { const extrasContent = p.extras.map(e => { const eName = App.Utils.getLocalizedText(e.name); const eVal = typeof e.name === 'string' ? e.name : e.name.en; return `<div class="extra-item"><div class="form-check m-0"><input class="form-check-input extra-check" type="checkbox" value="${eVal}" id="ex-${eVal.replace(/\s+/g,'')}" data-price="${e.price}"><label class="form-check-label small" for="ex-${eVal.replace(/\s+/g,'')}">${eName}</label></div><span class="text-primary fw-bold small">+${App.Utils.fmt(e.price)}</span></div>`; }).join(''); extrasHtml = `<div class="mb-4 bg-light p-3 rounded"><h6 class="small fw-bold text-muted mb-2" data-i18n="lbl_extras">${App.I18n.t('lbl_extras')}</h6>${extrasContent}</div>`; }
            let reviewsHtml = `<div class="mt-4 border-top pt-3"><h6 class="fw-bold mb-3" data-i18n="lbl_reviews">${App.I18n.t('lbl_reviews')}</h6><div id="qv-reviews-list"><div class="spinner-border spinner-border-sm text-primary"></div></div></div>`;
            return `<div class="row g-0" id="qv-content-wrapper"><div class="col-md-5 qv-img-container"><img src="${p.image || IMG_FALLBACK}" class="qv-img img-fade" onload="this.style.opacity=1" style="pointer-events:none; user-select:none;"/></div><div class="col-md-7 p-4 d-flex flex-column"><div class="d-flex justify-content-between align-items-start"><div><h4 class="fw-bold mb-1">${displayTitle}</h4><span class="badge bg-secondary">${App.I18n.t('cat_' + p.category.toLowerCase().replace(/\s+/g, '_'))}</span></div><button class="btn-close" data-bs-dismiss="modal" type="button"></button></div><div class="text-muted small mb-3">${cleanDesc || App.I18n.t('txt_prem_ing')}</div><div class="mb-4"><label class="small fw-bold text-muted mb-2" style="font-size:0.7rem">${App.I18n.t('lbl_size_var')}</label><div class="btn-group w-100 btn-pill-group" role="group"><input type="radio" class="btn-check" name="qv-size" id="size-reg" value="1" checked="checked" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-reg">${App.I18n.t('opt_regular')}</label><input type="radio" class="btn-check" name="qv-size" id="size-box" value="1.2" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-box">${App.I18n.t('opt_box')}</label><input type="radio" class="btn-check" name="qv-size" id="size-party" value="1.5" onchange="App.QuickView.updatePrice(${p.price_MAD}, ${p.old_price_MAD})"><label class="btn btn-outline-secondary" for="size-party">${App.I18n.t('opt_party')}</label></div></div>${extrasHtml}<div class="d-flex justify-content-between align-items-center pt-3 border-top mt-auto">${priceHtml}<div class="d-flex gap-2 align-items-center"><div class="input-group input-group-sm" style="width:100px"><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(-1); return false;">-</button><input type="number" value="1" min="1" id="qv-qty" class="form-control text-center border-0" readonly><button class="btn btn-outline-secondary" type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.updateQty(1); return false;">+</button></div><button class="btn btn-dark btn-sm rounded-pill fw-bold px-4 py-2" ${stock.disabled ? 'disabled' : ''} type="button" onclick="event.preventDefault(); event.stopPropagation(); App.QuickView.addToCart('${safeId}'); return false;">${App.I18n.t('btn_add_caps')}</button></div></div>${relatedHtml}${reviewsHtml}</div></div></div>`; 
        },
        renderReviews: (reviews, container) => { /* ... existing ... */ 
            if(reviews.length === 0) { container.innerHTML = '<p class="text-muted small">No reviews yet.</p>'; return; }
            container.innerHTML = reviews.map(r => `<div class="review-card"><div class="d-flex justify-content-between mb-1"><span class="fw-bold small">${r.user}</span><span class="text-warning small"><i class="bi bi-star-fill"></i> ${r.rating}</span></div><p class="small text-muted m-0">${r.comment}</p></div>`).join('');
        },
        updatePrice: (base, oldBase) => { const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value); document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult); const oldEl = document.getElementById('qv-old-price-display'); if(oldEl && oldBase) oldEl.innerText = App.Utils.fmt(oldBase * mult); },
        updateQty: (delta) => { const el = document.getElementById('qv-qty'); if(!el) return; let val = parseInt(el.value) || 1; val += delta; if(val < 1) val = 1; el.value = val; },
        addToCart: (id) => { 
            const qtyInput = document.getElementById('qv-qty'); 
            let sizeInput = document.querySelector('input[name="qv-size"]:checked'); 
            if(!sizeInput) sizeInput = document.getElementById('size-reg'); 
            const qty = qtyInput ? parseInt(qtyInput.value) : 1; 
            const el = sizeInput || { value: 1, id: 'size-reg' }; 
            let labelText = "Regular"; 
            if(sizeInput) { const label = document.querySelector(`label[for="${sizeInput.id}"]`); if(label) labelText = label.innerText; } 
            const extras = []; 
            document.querySelectorAll('.extra-check:checked').forEach(c => extras.push(c.value)); 
            const variant = { mult: parseFloat(el.value), name: labelText }; 
            App.Cart.add(id, null, qty, variant, extras); 
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); 
        },
        checkUpsell: (triggerCategory) => { /* ... existing ... */
            const targetCat = App.State.upsellRules[triggerCategory]; if (!targetCat) return; const suggestItem = App.State.catalog.find(i => i.category === targetCat);
            if (suggestItem && !App.State.cart.find(c => c.id === suggestItem.id)) { App.UI.showUpsellToast(suggestItem); App.State.hasUpsold = true; setTimeout(() => { App.State.hasUpsold = false; }, 60000); }
        },
        showUpsellToast: (item) => { /* ... existing ... */
             const title = App.Utils.getLocalizedText(item.title); const price = App.Utils.fmt(item.price_MAD); const img = item.image || IMG_FALLBACK; const safeId = String(item.id).replace(/'/g, "\\'");
             const html = `<div class="custom-toast border-primary" style="background:#fff; border-left:4px solid var(--primary);"><div class="d-flex align-items-center gap-3"><img src="${img}" style="width:50px; height:50px; object-fit:cover; border-radius:8px;"><div><div class="small text-muted fw-bold">Want a drink?</div><div class="fw-bold" style="font-size:0.9rem">${title}</div><div class="text-primary small fw-bold">${price}</div></div><button class="btn btn-sm btn-dark rounded-pill ms-auto px-3" onclick="App.Cart.add('${safeId}', this); this.closest('.custom-toast').remove()">+ Add</button><button class="btn-close ms-1" onclick="this.closest('.custom-toast').remove()"></button></div></div>`;
             const container = document.getElementById('toast-container'); if(container) { container.innerHTML = ''; const div = document.createElement('div'); div.innerHTML = html; container.appendChild(div.firstElementChild); const audio = document.getElementById('admin-sound'); if(audio) { audio.volume = 0.2; audio.play().catch(e=>{}); } }
        }
    },

    // 7. CART & CHECKOUT
    Cart: {
        add: (id, btn, qty=1, variant={mult:1, name:'Regular'}, extras=[]) => { 
            const p = App.State.catalog.find(x => String(x.id) === String(id)); 
            if(!p) return; 

            if(btn) { 
                btn.classList.add('btn-clicked'); 
                setTimeout(() => btn.classList.remove('btn-clicked'), 150); 
                let imgEl = null;
                const card = btn.closest('.product-card');
                const toast = btn.closest('.custom-toast');
                if (card) imgEl = card.querySelector('.product-img');
                else if (toast) imgEl = toast.querySelector('img');
                if(imgEl) App.UI.flyToCart(imgEl); 
            } 

            let existing = App.State.cart.find(x => x.id === id && x.variant.name === variant.name && JSON.stringify(x.extras.sort()) === JSON.stringify(extras.sort())); 
            if(existing) { existing.qty += qty; } 
            else { App.State.cart.push({ id: id, qty: qty, title: p.title, price: p.price_MAD, image: p.image, variant: variant, extras: extras }); } 

            App.Utils.save('se_cart', App.State.cart); 
            App.UI.showCartNotification(); 
            App.UI.toast(App.I18n.t('cart_updated'), 'success'); 

            if(App.State.currentView === 'cart') App.Cart.render(); 
            if(App.State.user) App.API.push('cart'); 

            // Trigger Upsell (Check if click came from toast to prevent loop)
            const isUpsellClick = btn && btn.closest('.custom-toast');
            if (!App.State.hasUpsold && !isUpsellClick) {
               App.UI.checkUpsell(p.category);
            }
        },
        remove: (idx) => { App.UI.confirm(App.I18n.t('cart_remove_title'), App.I18n.t('cart_remove_msg'), () => { App.State.cart.splice(idx, 1); App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); }); },
        update: (idx, delta) => { if(App.State.cart[idx].qty + delta < 1) return; App.State.cart[idx].qty += delta; App.Utils.save('se_cart', App.State.cart); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); },
        empty: () => { if(App.State.cart.length === 0) return; App.UI.confirm(App.I18n.t('cart_empty_title'), App.I18n.t('cart_empty_msg'), () => { App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); App.UI.showCartNotification(); if(App.State.user) App.API.push('cart'); }); },
        render: () => {
            const el = document.getElementById('cart-list'); const empty = document.getElementById('cart-empty-state'); const content = document.getElementById('cart-content'); const badge = document.getElementById('nav-cart-count'); 
            if(badge) badge.innerText = App.State.cart.reduce((a,b)=>a+b.qty,0);
            if(App.State.cart.length === 0) { if(empty) empty.classList.remove('d-none'); if(content) content.classList.add('d-none'); } 
            else {
                if(empty) empty.classList.add('d-none'); if(content) content.classList.remove('d-none'); 
                if(el) {
                    let html = App.State.cart.map((i, idx) => {
                        const basePrice = i.price * i.variant.mult; let extraCost = 0; let translatedExtrasList = [];
                        if(i.extras) { i.extras.forEach(eName => { const pObj = App.State.catalog.find(x => String(x.id) === String(i.id)); if(pObj && pObj.extras) { const found = pObj.extras.find(ex => (typeof ex.name === 'string' ? ex.name : ex.name.en) === eName); if(found) { extraCost += Number(found.price); translatedExtrasList.push(App.Utils.getLocalizedText(found.name)); } else { translatedExtrasList.push(eName); } } else { translatedExtrasList.push(eName); } }); } 
                        const finalUnit = basePrice + extraCost; const total = finalUnit * i.qty; const extrasDisplay = translatedExtrasList.length > 0 ? `<div class="small text-muted">+ ${translatedExtrasList.join(', ')}</div>` : '';
                        return `<div class="cart-item-card"><img src="${App.Utils.optimizeImg(i.image || IMG_FALLBACK)}" class="cart-item-img"/> <div class="flex-grow-1"> <div class="d-flex justify-content-between align-items-start"> <div> <h6 class="fw-bold mb-1">${App.Utils.getLocalizedText(i.title)}</h6> <div class="small text-muted">${i.variant.name !== 'Regular' ? i.variant.name : ''}</div> ${extrasDisplay} <div class="text-primary fw-bold mt-1">${App.Utils.fmt(finalUnit)}</div> </div> <i class="bi bi-trash text-danger action-icon" onclick="App.Cart.remove(${idx})"></i> </div> <div class="d-flex justify-content-between align-items-end mt-2"> <div class="qty-selector"> <button class="qty-btn" onclick="App.Cart.update(${idx}, -1)">-</button> <span class="px-2 small fw-bold">${i.qty}</span> <button class="qty-btn" onclick="App.Cart.update(${idx}, 1)">+</button> </div> <span class="fw-bold">${App.Utils.fmt(total)}</span> </div> </div> </div>`;
                    }).join('');
                    const hasDrinks = App.State.cart.some(c => { const p = App.State.catalog.find(x => String(x.id) === String(c.id)); return p && (p.category === 'Drinks' || p.category === 'Boissons'); });
                    if(!hasDrinks) {
                        const drinks = App.State.catalog.filter(x => x.category === 'Drinks' || x.category === 'Boissons').slice(0, 4);
                        if(drinks.length > 0) {
                            html += `<div class="mt-4 mb-2"><h6 class="fw-bold small text-muted text-uppercase" data-i18n="msg_upsell_side">${App.I18n.t('msg_upsell_side')}</h6><div class="d-flex gap-2 overflow-auto pb-2" style="scrollbar-width:none">` + drinks.map(d => `<div class="border rounded p-2" style="min-width:140px; background:#fff; cursor:pointer;" onclick="App.Cart.add('${String(d.id).replace(/'/g, "\\'")}', this)"><div class="d-flex align-items-center gap-2"><img src="${d.image || IMG_FALLBACK}" style="width:40px; height:40px; object-fit:cover; border-radius:6px;"><div style="line-height:1.1"><div class="small fw-bold text-truncate" style="max-width:80px">${App.Utils.getLocalizedText(d.title)}</div><div class="small text-primary fw-bold">${App.Utils.fmt(d.price_MAD)}</div></div><div class="ms-auto"><i class="bi bi-plus-circle-fill text-success"></i></div></div></div>`).join('') + `</div></div>`;
                        }
                    }
                    el.innerHTML = html;
                } 
                App.Cart.calculateTotal();
            }
        },
        calculateTotal: () => {
            let sub = 0; App.State.cart.forEach(i => { const base = i.price * i.variant.mult; let extra = 0; if(i.extras) { i.extras.forEach(eName => { const pObj = App.State.catalog.find(x => String(x.id) === String(i.id)); if(pObj && pObj.extras) { const found = pObj.extras.find(ex => (typeof ex.name === 'string' ? ex.name : ex.name.en) === eName); if(found) extra += Number(found.price); } }); } sub += (base + extra) * i.qty; });
            const zoneEl = document.getElementById('chk-zone'); const zone = zoneEl ? zoneEl.value : ''; const shipCost = (zone && App.Config.deliveryZones['Delivery_' + zone]) ? App.Config.deliveryZones['Delivery_' + zone] : 0; const freeShip = sub >= App.Config.freeShipThreshold; const finalShip = freeShip ? 0 : shipCost; 
            const barFill = document.getElementById('delivery-bar-fill'); const msgEl = document.getElementById('delivery-msg'); const amtEl = document.getElementById('delivery-amt');
            if(barFill && msgEl && amtEl) { const pct = Math.min((sub / App.Config.freeShipThreshold) * 100, 100); barFill.style.width = pct + '%'; if(pct >= 100) { barFill.style.background = '#198754'; msgEl.innerText = App.I18n.t('lbl_delivery_free'); msgEl.className = 'text-success fw-bold'; amtEl.innerText = ""; } else { barFill.style.background = '#ffc107'; const remain = App.Config.freeShipThreshold - sub; msgEl.innerText = App.I18n.t('lbl_delivery_more'); msgEl.className = 'text-muted'; amtEl.innerText = App.Utils.fmt(remain); } }
            let discount = 0; if(App.State.activeCoupon) discount = sub * App.State.activeCoupon.discount; 
            let pointsDiscount = 0; const usePoints = document.getElementById('use-points-switch'); const rowPoints = document.getElementById('row-points'); const pointsVal = document.getElementById('cart-points-disc'); const pointsDisplay = document.getElementById('points-balance-display');
            if(pointsDisplay && App.State.user) { pointsDisplay.innerText = `(${App.State.user.points} ${App.I18n.t('lbl_pts')})`; }
            if (usePoints && usePoints.checked && App.State.user) { const maxDiscount = sub * 0.50; const userPointsVal = App.State.user.points / 10; pointsDiscount = Math.min(maxDiscount, userPointsVal); if(rowPoints) rowPoints.classList.remove('d-none'); if(pointsVal) pointsVal.innerText = "-" + App.Utils.fmt(pointsDiscount); } else { if(rowPoints) rowPoints.classList.add('d-none'); }
            const total = sub + finalShip - discount - pointsDiscount; 
            if(document.getElementById('cart-subtotal')) document.getElementById('cart-subtotal').innerText = App.Utils.fmt(sub);
            if(document.getElementById('cart-delivery')) document.getElementById('cart-delivery').innerText = freeShip ? App.I18n.t('lbl_free') : App.Utils.fmt(finalShip);
            if(document.getElementById('cart-total')) document.getElementById('cart-total').innerText = App.Utils.fmt(total);
            if(discount > 0) { document.getElementById('row-disc').classList.remove('d-none'); document.getElementById('cart-disc').innerText = '-' + App.Utils.fmt(discount); } else { document.getElementById('row-disc').classList.add('d-none'); }
            if(App.Cart.renderCoupons) App.Cart.renderCoupons();
        },
        applyCoupon: () => { const code = document.getElementById('coupon-code').value.trim(); if(!code) return; const sub = App.State.cart.reduce((a,b) => a + (b.price * b.variant.mult * b.qty), 0); const fb = document.getElementById('coupon-feedback'); fb.innerText = App.I18n.t('msg_verifying'); fb.className = 'small text-end mb-2 text-warning'; fetch(API_URL, {method:'POST', body:JSON.stringify({action:'checkCoupon', data:{ code: code, total: sub }})}).then(r=>r.json()).then(res => { if(res.status === 'success') { App.State.activeCoupon = res; fb.innerText = `${res.code} ${App.I18n.t('msg_applied')}`; fb.className = 'small text-end mb-2 text-success fw-bold'; App.Cart.calculateTotal(); } else { App.State.activeCoupon = null; fb.innerText = res.message || App.I18n.t('msg_code_invalid'); fb.className = 'small text-end mb-2 text-danger'; App.Cart.calculateTotal(); } }); },
        renderCoupons: () => {
            const container = document.getElementById('available-coupons'); if(!container) return; const subtotal = App.State.cart.reduce((a,b) => a + (b.price * b.variant.mult * b.qty), 0); if(App.State.coupons.length === 0) { container.innerHTML = ''; return; }
            container.innerHTML = `<h6 class="small fw-bold text-muted mb-2">${App.I18n.t('lbl_avail_coupons')}</h6>` + App.State.coupons.map(c => { const isUnlocked = subtotal >= c.min; const diff = c.min - subtotal; const bgClass = isUnlocked ? "bg-light border-success" : "bg-light opacity-75"; const textClass = isUnlocked ? "text-success" : "text-muted"; const btnHtml = isUnlocked ? `<button class="btn btn-sm btn-success rounded-pill px-3" onclick="document.getElementById('coupon-code').value='${c.code}'; App.Cart.applyCoupon()">${App.I18n.t('btn_apply')}</button>` : `<small class="text-danger fw-bold" style="font-size:0.7rem">${App.I18n.t('lbl_add_more')} ${App.Utils.fmt(diff)}</small>`; return `<div class="d-flex justify-content-between align-items-center p-2 mb-2 border rounded ${bgClass}"><div><div class="fw-bold small ${textClass}">${c.code}</div><div class="small text-muted" style="font-size:0.75rem">${c.desc}</div></div>${btnHtml}</div>`; }).join('');
        },
        renderZones: (config) => { const s = document.getElementById('chk-zone'); if(!s) return; s.innerHTML = `<option value="">${App.I18n.t('select_zone_ph')}</option>`; Object.keys(config).forEach(k => { if(k.startsWith('Delivery_')) { const zoneName = k.replace('Delivery_', ''); const tKey = 'zone_' + zoneName.toLowerCase(); const label = (App.State.translations[tKey]) ? App.I18n.t(tKey) : zoneName; s.innerHTML += `<option value="${zoneName}">${label} (${config[k]} DH)</option>`; } }); },
        fillAddress: () => { const sel = document.getElementById('cart-addr-select'); if(!sel || !sel.value) return; const type = sel.value.toLowerCase(); const data = App.State.addresses[type]; if(data) { document.getElementById('chk-address').value = (typeof data === 'string') ? data : data.full; document.getElementById('chk-zone').focus(); } },
        togglePoints: () => { App.Cart.calculateTotal(); },
        reorder: (itemsJsonStr) => { try { let items = []; if (itemsJsonStr.startsWith('[')) { items = JSON.parse(itemsJsonStr); } else { items = [itemsJsonStr]; } let addedCount = 0; items.forEach(itemStr => { const regex = /^(\d+)x\s(.+)$/; const match = itemStr.match(regex); if (match) { const qty = parseInt(match[1]); let rest = match[2]; let extras = []; if (rest.includes('(') && rest.includes(')')) { const parts = rest.split('('); rest = parts[0].trim(); const extrasStr = parts[1].replace(')', ''); extras = extrasStr.split(',').map(s => s.trim()); } let foundProd = null; for(let i=0; i<App.State.catalog.length; i++) { const p = App.State.catalog[i]; if ( (typeof p.title === 'object' && (p.title.en === rest || p.title.fr === rest || p.title.ar === rest)) || (typeof p.title === 'string' && p.title === rest) ) { foundProd = p; break; } } if (foundProd) { const variant = {mult: 1, name: 'Regular'}; App.Cart.add(foundProd.id, null, qty, variant, extras); addedCount++; } } }); if (addedCount > 0) { App.Router.go('cart'); App.UI.toast(`${addedCount} items added to cart`, 'success'); } else { App.UI.toast("Could not find items", 'error'); } } catch (e) { console.error("Reorder failed", e); App.UI.toast("Error reordering", 'error'); } }
    },

	// 7.5 WISHLIST (MISSING MODULE FIXED)
    Wishlist: {
        toggle: (id) => {
            const idx = App.State.wishlist.indexOf(String(id));
            // Check if item exists in wishlist
            if(idx > -1) {
                // Remove it
                App.State.wishlist.splice(idx, 1);
                App.UI.toast(App.I18n.t('msg_wish_removed'));
                App.UI.updateHearts(id, false);
            } else {
                // Add it
                App.State.wishlist.push(String(id));
                App.UI.toast(App.I18n.t('msg_wish_added'), 'success');
                App.UI.updateHearts(id, true);

                // Trigger Upsell Logic on Wishlist add (optional)
                const p = App.State.catalog.find(x => String(x.id) === String(id));
                if(p && !App.State.hasUpsold) App.UI.checkUpsell(p.category);
            }

            // Save to LocalStorage
            App.Utils.save('se_wish', App.State.wishlist);

            // Update Badge
            const badge = document.getElementById('nav-wish-count');
            if(badge) badge.innerText = App.State.wishlist.length;

            // Sync with Server if logged in
            if(App.State.user) App.API.push('wish');

            // Re-render if currently on wishlist page
            if(App.State.currentView === 'wishlist') App.Wishlist.render();
        },

        render: () => {
            // 1. Render in Profile Tab
            const gridProfile = document.getElementById('profile-wishlist-grid');

            // 2. Render in Main Module (if you have a separate page)
            const moduleContainer = document.getElementById('wishlist-module');

            // Logic to generate HTML
            let html = '';
            if(App.State.wishlist.length === 0) {
                html = `<div class="col-12 text-center text-muted py-5">
                    <i class="bi bi-heart display-1 text-light"></i>
                    <p class="mt-3">${App.I18n.t('wishlist_empty')}</p>
                    <button class="btn btn-outline-primary rounded-pill" onclick="App.Router.go('catalog')">${App.I18n.t('btn_shop')}</button>
                </div>`;
            } else {
                const items = App.State.wishlist.map(id => {
                    const p = App.State.catalog.find(x => String(x.id) === String(id));
                    return p ? App.UI.renderCard(p, true) : ''; 
                }).join('');
                html = items;
            }

            // Apply HTML to containers
            if(gridProfile) gridProfile.innerHTML = html;
            if(moduleContainer) {
                moduleContainer.innerHTML = `
                    <div class="container">
                        <h2 class="fw-bold mb-4">${App.I18n.t('nav_wishlist')}</h2>
                        <div class="row gy-4">${html}</div>
                    </div>`;
            }
        }
    },

    // 8. API (UPGRADED: STATUS NOTIFICATIONS)
    API: {
        init: () => {
            fetch(API_URL + '?action=checkStoreStatus').then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                    App.Config = {...App.Config, ...res.config, deliveryZones: res.config};
                    App.Cart.renderZones(res.config);
                    if(!res.isOpen) {
                        const badge = document.getElementById('store-float-badge');
                        if(badge) badge.classList.add('active');
                    }   
                }
            });

            fetch(API_URL + '?action=getCoupons').then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                    App.State.coupons = res.data;
                    if(App.Cart.renderCoupons) App.Cart.renderCoupons();
                }
            });

            fetch(API_URL + '?action=getCatalog').then(r=>r.json()).then(res => {
                if(res.status === 'success') {
                    App.State.catalog = res.data;
                    App.Catalog.renderFilters();
                    App.Catalog.renderBatch(true);
                    if(App.Catalog.renderRecent) App.Catalog.renderRecent(); 

                    // Initial User Fetch
                    if(App.State.user) App.API.fetchUserData();
                }
            });
            App.I18n.fetch();
        },

        fetchUserData: (isPolling = false) => {
            const u = App.State.user;
            if (!u) return;

            // Don't show global loader if we are just background polling
            if (!isPolling) App.UI.showReload();

            fetch(API_URL + '?action=getUserData&userId=' + u.id + '&token=' + u.authToken)
            .then(r=>r.json()).then(res => {
                // Remove loader immediately if it was shown
                if (!isPolling) App.UI.hideLoader();

                if(res.status === 'success') {
                    if(res.wishlist) App.State.wishlist = res.wishlist.split(',');
                    // Only overwrite local cart if it's empty (prevents overwriting user activity)
                    if(res.cart && App.State.cart.length === 0) App.State.cart = JSON.parse(res.cart);
                    if(res.currency) App.State.currency = res.currency;
                    if(res.orders) App.State.history = res.orders;
                    if(res.addresses) App.State.addresses = res.addresses;
                    if(res.profile && res.profile.points) App.State.user.points = res.profile.points;
                    if(res.recent) {
                         const combined = [...new Set([...res.recent, ...App.State.recent])];
                         App.State.recent = combined.slice(0, 12);
                         App.Utils.save('se_recent', App.State.recent);
                         if(App.Catalog.renderRecent) App.Catalog.renderRecent();
                    }

                    App.State.exchange['MAD'] = 1;
                    App.Utils.save('se_user', App.State.user);

                    // --- NOTIFICATION LOGIC START ---
                    // Check the latest order status against local storage
                    if (res.orders && res.orders.length > 0) {
                        const latest = res.orders[0]; // Newest order
                        const storageKey = 'se_last_stat_' + latest.id;
                        const lastKnownStatus = localStorage.getItem(storageKey);

                        // If we have a saved status AND it's different from current (and not just created)
                        if (lastKnownStatus && lastKnownStatus !== latest.status) {
                            const statusKey = 'status_' + latest.status.toLowerCase().replace(/\s/g,'_');
                            const statusText = App.I18n.t(statusKey) || latest.status;

                            // 1. Show Toast
                            App.UI.toast(`🔔 Order #${latest.id}: ${statusText}`, 'success');

                            // 2. Play Sound
                            const audio = document.getElementById('admin-sound');
                            if(audio) audio.play().catch(e => console.log("Interaction needed for audio"));

                            // 3. Refresh History UI if visible
                            App.Profile.renderHistory();
                        }

                        // Update local storage with new status
                        localStorage.setItem(storageKey, latest.status);
                    }
                    // --- NOTIFICATION LOGIC END ---

                    if (!isPolling) {
                        App.Cart.render();
                        App.Auth.check();
                    }
                }
            }).catch(e => { if(!isPolling) App.UI.hideLoader(); });
        },

        push: (type) => {
            const u = App.State.user; if(!u) return;
            let action = '', data = { userId: u.id, authToken: u.authToken };
            if(type === 'cart') { action = 'syncCart'; data.cartJson = JSON.stringify(App.State.cart); data.currency = App.State.currency; }
            if(type === 'wish') { action = 'syncWishlist'; data.items = App.State.wishlist.join(','); }
            if(type === 'pref') { action = 'updatePreference'; data.currency = App.State.currency; }
            if(action) fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: action, data: data }) });
        },

        checkout: () => { 
            const n = document.getElementById('chk-name').value;
            const p = document.getElementById('chk-phone').value;
            const a = document.getElementById('chk-address').value;
            const z = document.getElementById('chk-zone').value;
            const m = document.getElementById('chk-payment') ? document.getElementById('chk-payment').value : 'cod';
            const note = document.getElementById('order-note').value;
            const usePoints = document.getElementById('use-points-switch') ? document.getElementById('use-points-switch').checked : false;

            if(App.State.cart.length === 0) return alert(App.I18n.t('cart_empty'));
            if(!n || !p || !a || !z) return alert(App.I18n.t('msg_fill_fields'));
            if(!App.Utils.isValidPhone(p)) return alert(App.I18n.t('msg_invalid_phone'));

            const btn = document.getElementById('checkout-btn');
            if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_processing'); } 

            const cartData = App.State.cart.map(i => {
                let cleanTitle = i.title;
                if (typeof i.title === 'object' && i.title !== null) {
                    cleanTitle = i.title[App.State.lang] || i.title['en'] || "Item";
                }
                return { id: i.id, qty: i.qty, variantMult: i.variant.mult, title: cleanTitle, extras: i.extras };
            });

            const orderData = { 
                userId: App.State.user ? App.State.user.id : 'Guest', 
                authToken: App.State.user ? App.State.user.authToken : null, 
                name: n, phone: p, zone: z, address: `${z} - ${a}`, 
                cart: JSON.stringify(cartData), method: m, 
                couponCode: App.State.activeCoupon ? App.State.activeCoupon.code : null,
                usePoints: usePoints
            }; 

            fetch(API_URL, { method: 'POST', headers: { "Content-Type": "text/plain;charset=utf-8" }, body: JSON.stringify({ action: 'placeOrder', data: orderData }) })
            .then(r => r.json()).then(res => { 
                if(res.status === 'success') { 
                    App.State.cart.forEach(c => { if(!App.State.wishlist.includes(String(c.id))) App.State.wishlist.push(String(c.id)); }); 
                    App.Utils.save('se_wish', App.State.wishlist); 
                    if(App.State.user) App.API.push('wishlist'); 

                    if(App.State.user && res.pointsRedeemed > 0) {
                        App.State.user.points = Math.max(0, App.State.user.points - res.pointsRedeemed);
                        App.Profile.updatePointsUI();
                        App.Utils.save('se_user', App.State.user);
                    }

                    App.State.cart = []; App.Utils.save('se_cart', []); App.Cart.render(); 

                    const wa_new_order = App.I18n.t('wa_new_order'); 
                    const wa_total = App.I18n.t('wa_total'); 
                    const wa_1h = App.I18n.t('wa_1h'); 

                    let msg = `*${wa_new_order} ${res.orderId}*%0A`; 
                    msg += `👤 ${n} (${p})%0A🚚 ${orderData.address}%0A💳 ${m === 'cp' ? 'Cash Plus' : 'COD'}%0A🕒 ${wa_1h}%0A📝 ${note}%0A--------------------%0A`; 

                    cartData.forEach(i => { 
                        msg += `🍱 ${i.qty}x ${i.title}`; 
                        if(i.extras && i.extras.length>0) msg+= ` + ${i.extras.join(',')}`; 
                        msg += `%0A`; 
                    }); 

                    msg += `💰 *${wa_total}: ${App.Utils.fmt(res.secureTotal)}*`; 

                    const waLink = `https://wa.me/${App.Config.waNumber}?text=${msg}`;

                    document.getElementById('cart-content').classList.add('d-none'); 
                    document.getElementById('cart-empty-state').classList.add('d-none');
                    const container = document.getElementById('cart-module').querySelector('.container');
                    container.innerHTML = `<div class="text-center py-5 fade-in"><div class="mb-4"><i class="bi bi-check-circle-fill text-success display-1"></i></div><h2 class="fw-bold mb-3">${App.I18n.t('msg_order_confirmed')}</h2><p class="text-muted mb-4 lead">${App.I18n.t('msg_order_redirect')}</p><a href="${waLink}" target="_blank" class="btn btn-success rounded-pill px-5 py-3 fw-bold shadow mb-4"><i class="bi bi-whatsapp me-2"></i> ${App.I18n.t('btn_whatsapp')}</a><br/><button class="btn btn-link text-muted text-decoration-none" onclick="location.reload()">${App.I18n.t('btn_back_home')}</button></div>`;
                    const sticky = document.getElementById('sticky-checkout-bar'); 
                    if(sticky) sticky.remove();

                    if(window.confetti) confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });

                    // --- INIT STATUS TRACKING FOR NEW ORDER ---
                    localStorage.setItem('se_last_stat_' + res.orderId, 'Pending');

                } else { 
                    alert("Server Error: " + res.message); 
                    if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_checkout'); } 
                } 
            }).catch(e => { 
                console.error(e); 
                alert("Connection failed."); 
                if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_checkout'); } 
            }); 
        },
        bookTable: () => {
             const d = {
                name: document.getElementById('res-name').value,
                phone: document.getElementById('res-phone').value,
                date: document.getElementById('res-date').value,
                time: document.getElementById('res-time').value,
                guests: document.getElementById('res-guests').value,
                userId: App.State.user ? App.State.user.id : 'Guest'
            };
            if(!d.name || !d.phone || !d.date || !d.time) return alert(App.I18n.t('msg_fill_fields'));

            const btn = document.getElementById('btn-book-table');
            btn.disabled = true; 
            btn.innerText = App.I18n.t('btn_processing');

            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'bookTable', data:d})}).then(r=>r.json()).then(res=>{
                btn.disabled = false; btn.innerText = App.I18n.t('btn_book_now');
                if(res.status==='success') {
                    alert(App.I18n.t('msg_res_sent'));
                    App.Router.go('home');
                } else alert(res.message);
            });
        },
        submitReview: () => {
            if(!App.State.user) return alert("Login to review");
            if(App.State.tempRating === 0) return alert("Select a star rating");
            const txt = document.getElementById('review-comment').value;
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'submitReview', data:{
                userId: App.State.user.id,
                userName: App.State.user.name,
                productId: App.State.tempReviewPid,
                rating: App.State.tempRating,
                comment: txt
            }})}).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    App.UI.toast("Review Submitted!");
                    bootstrap.Modal.getInstance(document.getElementById('reviewModal')).hide();
                }
            });
        },

        updateLang: (l) => {
            const u = App.State.user;
            if(!u) return;
            fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'updateUser', data: { userId: u.id, authToken: u.authToken, lang: l } }) });
        }
    },

    // 9. QUICK VIEW (Handled in UI)
    QuickView: {
        open: (id) => {
            const p = App.State.catalog.find(x => String(x.id) === String(id));
            if(!p) return;

            // --- 1. LOCAL STORAGE LOGIC ---
            // Remove duplicates and move to top
            const currentRecent = App.State.recent.filter(x => String(x) !== String(id));
            currentRecent.unshift(String(id));

            // Keep max 12 items
            if(currentRecent.length > 12) currentRecent.pop();

            App.State.recent = currentRecent;
            App.Utils.save('se_recent', currentRecent);

            // UPDATE THE UI IMMEDIATELY
            if(App.Catalog.renderRecent) App.Catalog.renderRecent();

            // --- 2. SERVER SYNC LOGIC (With AuthToken) ---
            if(App.State.user) {
                fetch(API_URL, {
                    method: 'POST',
                    body: JSON.stringify({
                        action: 'logView',
                        data: { 
                            userId: App.State.user.id, 
                            authToken: App.State.user.authToken, // <--- CRITICAL FIX
                            productId: id 
                        }
                    })
                }).catch(err => console.log("View log error", err));
            }

            // --- 3. REVIEWS & MODAL (Existing Code) ---
            if(!p.reviewsLoaded) {
                 fetch(API_URL + '?action=getReviews&productId=' + id).then(r=>r.json()).then(res=>{
                     if(res.status==='success') {
                         p.reviews = res.data;
                         p.reviewsLoaded = true;
                         const list = document.getElementById('qv-reviews-list');
                         if(list && document.getElementById('qv-body').innerHTML.includes(App.Utils.getLocalizedText(p.title))) {
                             App.QuickView.renderReviews(p.reviews, list);
                         }
                     }
                 });
            }

            document.getElementById('qv-body').innerHTML = App.UI.renderQuickView(p);
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();

            const list = document.getElementById('qv-reviews-list');
            if(p.reviewsLoaded) App.QuickView.renderReviews(p.reviews, list);
        },
        renderReviews: (reviews, container) => {
            if(reviews.length === 0) { container.innerHTML = '<p class="text-muted small">No reviews yet.</p>'; return; }
            container.innerHTML = reviews.map(r => `
                <div class="review-card">
                    <div class="d-flex justify-content-between mb-1">
                        <span class="fw-bold small">${r.user}</span>
                        <span class="text-warning small"><i class="bi bi-star-fill"></i> ${r.rating}</span>
                    </div>
                    <p class="small text-muted m-0">${r.comment}</p>
                </div>
            `).join('');
        },
        updatePrice: (base, oldBase) => { const mult = parseFloat(document.querySelector('input[name="qv-size"]:checked').value); document.getElementById('qv-price-display').innerText = App.Utils.fmt(base * mult); const oldEl = document.getElementById('qv-old-price-display'); if(oldEl && oldBase) oldEl.innerText = App.Utils.fmt(oldBase * mult); },
        updateQty: (delta) => { const el = document.getElementById('qv-qty'); if(!el) return; let val = parseInt(el.value) || 1; val += delta; if(val < 1) val = 1; el.value = val; },
        addToCart: (id) => { 
            const qtyInput = document.getElementById('qv-qty'); 
            let sizeInput = document.querySelector('input[name="qv-size"]:checked'); 
            if(!sizeInput) sizeInput = document.getElementById('size-reg'); 
            const qty = qtyInput ? parseInt(qtyInput.value) : 1; 
            const el = sizeInput || { value: 1, id: 'size-reg' }; 
            let labelText = "Regular"; 
            if(sizeInput) { const label = document.querySelector(`label[for="${sizeInput.id}"]`); if(label) labelText = label.innerText; } 
            const extras = []; 
            document.querySelectorAll('.extra-check:checked').forEach(c => extras.push(c.value)); 
            const variant = { mult: parseFloat(el.value), name: labelText }; 
            App.Cart.add(id, null, qty, variant, extras); 
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide(); 
        }, // <--- COMMA HERE IS CRITICAL

        checkUpsell: (triggerCategory) => {
            const targetCat = App.State.upsellRules[triggerCategory];
            if (!targetCat) return;

            // Find a product in the target category
            const suggestItem = App.State.catalog.find(i => i.category === targetCat);

            // If item found AND not already in cart
            if (suggestItem && !App.State.cart.find(c => c.id === suggestItem.id)) {
                App.UI.showUpsellToast(suggestItem);
                App.State.hasUpsold = true;
                setTimeout(() => { App.State.hasUpsold = false; }, 60000);
            }
        },

        showUpsellToast: (item) => {
            const title = App.Utils.getLocalizedText(item.title);
            const price = App.Utils.fmt(item.price_MAD);
            const img = item.image || IMG_FALLBACK;
            const safeId = String(item.id).replace(/'/g, "\\'");

            const html = `
            <div class="custom-toast border-primary" style="background:#fff; border-left:4px solid var(--primary);">
                <div class="d-flex align-items-center gap-3">
                    <img src="${img}" style="width:50px; height:50px; object-fit:cover; border-radius:8px;">
                    <div>
                        <div class="small text-muted fw-bold">Want a drink?</div>
                        <div class="fw-bold" style="font-size:0.9rem">${title}</div>
                        <div class="text-primary small fw-bold">${price}</div>
                    </div>
                    <button class="btn btn-sm btn-dark rounded-pill ms-auto px-3" onclick="App.Cart.add('${safeId}', this); this.closest('.custom-toast').remove()">
                        + Add
                    </button>
                    <button class="btn-close ms-1" onclick="this.closest('.custom-toast').remove()"></button>
                </div>
            </div>`;

            const container = document.getElementById('toast-container');
            if(container) {
                container.innerHTML = '';
                const div = document.createElement('div');
                div.innerHTML = html;
                container.appendChild(div.firstElementChild);

                const audio = document.getElementById('admin-sound'); 
                if(audio) { audio.volume = 0.2; audio.play().catch(e=>{}); }
            }
        }
    }, // <--- CLOSING BRACE FOR App.UI

    // 11. ADMIN (Upgraded with Print & Sound)
    Admin: {
        openLogin: () => new bootstrap.Modal(document.getElementById('adminLoginModal')).show(),

        login: () => { 
            const p = document.getElementById('admin-pw').value; 
            if(!p) return; 
            App.State.adminPw = p; 
            App.Admin.fetchDashboard(); 
        },

        // --- NEW: TAB SWITCHING ---
        switchTab: (tabName, btn) => {
            // 1. Toggle Button Active State
            const grp = btn.parentElement;
            Array.from(grp.children).forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            // 2. Toggle Tab Content
            const ordersTab = document.getElementById('admin-tab-orders');
            const analyticsTab = document.getElementById('admin-tab-analytics');

            // Safety check in case HTML isn't updated yet
            if(!ordersTab || !analyticsTab) return;

            if(tabName === 'orders') {
                ordersTab.classList.remove('d-none');
                analyticsTab.classList.add('d-none');
            } else {
                ordersTab.classList.add('d-none');
                analyticsTab.classList.remove('d-none');
            }
        },

        // --- NEW: RENDER CHARTS ---
        renderCharts: (data) => {
            if(!data || !data.bestSellers || typeof Chart === 'undefined') return;

            // 1. Best Sellers (Bar Chart)
            const ctx1 = document.getElementById('chart-best-sellers');
            if(ctx1) {
                if(window.bstChart instanceof Chart) window.bstChart.destroy();
                window.bstChart = new Chart(ctx1, {
                    type: 'bar',
                    data: {
                        labels: data.bestSellers.map(i => i.name),
                        datasets: [{
                            label: 'Units Sold',
                            data: data.bestSellers.map(i => i.qty),
                            backgroundColor: '#ce1212',
                            borderRadius: 6,
                            barPercentage: 0.6
                        }]
                    },
                    options: { 
                        responsive: true,
                        plugins: { legend: { display: false } }, 
                        scales: { y: { beginAtZero: true, grid: { display:false } }, x: { grid: { display:false } } } 
                    }
                });
            }

            // 2. Peak Hours (Line Chart)
            const ctx2 = document.getElementById('chart-peak-hours');
            if(ctx2) {
                // Ensure we have data points for all 24 hours
                const hours = Array.from({length: 24}, (_, i) => i);
                const counts = hours.map(h => {
                    const found = data.peakHours.find(p => parseInt(p.hour) === h);
                    return found ? found.count : 0;
                });

                if(window.peakChart instanceof Chart) window.peakChart.destroy();
                window.peakChart = new Chart(ctx2, {
                    type: 'line',
                    data: {
                        labels: hours.map(h => h + 'h'),
                        datasets: [{
                            label: 'Orders',
                            data: counts,
                            borderColor: '#2d3436',
                            backgroundColor: 'rgba(206, 18, 18, 0.05)',
                            borderWidth: 2,
                            pointRadius: 0,
                            fill: true,
                            tension: 0.4
                        }]
                    },
                    options: { 
                        responsive: true,
                        plugins: { legend: { display: false } }, 
                        scales: { y: { beginAtZero: true, ticks: {stepSize: 1} }, x: { grid: { display:false } } } 
                    }
                });
            }

            // 3. Top Customers (List)
            const custList = document.getElementById('top-customers-list');
            if(custList) {
                custList.innerHTML = data.topCustomers.map((c, i) => `
                    <div class="list-group-item d-flex justify-content-between align-items-center border-0 px-0">
                        <div class="d-flex align-items-center gap-2">
                            <span class="badge bg-light text-dark border rounded-circle" style="width:25px;height:25px;display:flex;align-items:center;justify-content:center">${i+1}</span>
                            <span class="fw-bold small">${c.name}</span>
                        </div>
                        <span class="badge bg-success bg-opacity-10 text-success rounded-pill border border-success border-opacity-25">${App.Utils.fmt(c.total)}</span>
                    </div>
                `).join('');
            }
        },

        fetchDashboard: () => {
            fetch(API_URL + '?action=getAdminDashboard&pw=' + App.State.adminPw).then(r=>r.json()).then(res=>{
                if(res.status==='success') {
                    const loginModal = bootstrap.Modal.getInstance(document.getElementById('adminLoginModal'));
                    if(loginModal) loginModal.hide();

                    App.Router.go('admin');

                    // Update Revenue
                    const revEl = document.getElementById('admin-revenue');
                    if(revEl) revEl.innerText = App.Utils.fmt(parseFloat(res.revenue));

                    // Update Store Status Button
                    const isManualClosed = res.config.Manual_Close === true;
                    const statusEl = document.getElementById('admin-store-status');
                    if(statusEl) {
                        statusEl.innerText = isManualClosed ? App.I18n.t('status_closed') : App.I18n.t('status_open');
                        statusEl.className = isManualClosed ? "h3 fw-bold text-danger" : "h3 fw-bold text-success";
                    }

                    // Sound Alert Logic
                    const currentPending = res.orders.filter(o => o.status === 'Pending').length;
                    if (App.State.lastPendingCount !== undefined && currentPending > App.State.lastPendingCount) {
                        const audio = document.getElementById('admin-sound');
                        if(audio) {
                            audio.play().catch(() => console.log("Audio requires interaction"));
                            App.UI.toast("🔔 NEW ORDER!", "warning");
                        }
                    }
                    App.State.lastPendingCount = currentPending;

                    // Render Orders
                    const list = document.getElementById('admin-orders-list');
                    if(list) {
                        if(res.orders.length === 0) list.innerHTML = `<p class="text-muted text-center py-4">${App.I18n.t('admin_no_orders')}</p>`;
                        else {
                            list.innerHTML = res.orders.map(o => {
                                const statusKey = 'status_' + o.status.toLowerCase().replace(/\s/g,'_');
                                const translatedStatus = App.I18n.t(statusKey) || o.status;
                                const safeId = o.id.replace(/[^a-zA-Z0-9-]/g, '');

                                // Clean up items string
                                let itemsDisplay = o.items;
                                try {
                                    const parsed = JSON.parse(o.items);
                                    itemsDisplay = parsed.map(i => 
                                        `<div class="text-truncate">• <b>${i.qty}x</b> ${typeof i.title==='object'? (i.title[App.State.lang]||i.title.en) : i.title}</div>`
                                    ).join('');
                                } catch(e) { /* keep as string */ }

                                // Map Link Logic
                                let mapLink = `http://googleusercontent.com/maps.google.com/maps?q=${encodeURIComponent(o.address + " Morocco")}`;
                                let addrLabel = o.address;
                                let addrClass = "text-muted";

                                if(o.address.includes("http")) {
                                    const urlMatch = o.address.match(/(https?:\/\/[^\s]+)/g);
                                    if(urlMatch) mapLink = urlMatch[0].replace("http://", "https://");
                                    addrLabel = `📍 ${App.I18n.t('lbl_gps_location')}`; 
                                    addrClass = "text-danger fw-bold";
                                }

                                return `
                                <div class="admin-card ${o.status==='Completed'?'completed':''}">
                                    <div class="d-flex justify-content-between border-bottom pb-2 mb-2">
                                        <strong>#${o.id}</strong>
                                        <span class="badge bg-light text-dark border">${translatedStatus}</span>
                                    </div>
                                    <div class="mb-2">
                                        <div class="fw-bold"><i class="bi bi-person"></i> ${o.name}</div>
                                        <div class="small"><i class="bi bi-telephone"></i> <a href="tel:${o.phone}" class="text-decoration-none text-secondary">${o.phone}</a></div>
                                        <div class="small mt-1">
                                            <a href="${mapLink}" target="_blank" class="text-decoration-none ${addrClass}">
                                                <i class="bi bi-geo-alt-fill"></i> ${addrLabel}
                                            </a>
                                        </div>
                                        <div class="small text-muted my-2 bg-light p-2 rounded" id="items-${safeId}">${itemsDisplay}</div>
                                        <div class="fw-bold text-primary text-end" id="total-${safeId}">${App.Utils.fmt(o.total)}</div>
                                    </div>
                                    <div class="d-flex gap-2 flex-wrap">
                                        <button class="btn btn-sm btn-warning flex-grow-1" onclick="App.Admin.updateStatus('${o.id}', 'Preparing')">${App.I18n.t('btn_prep')}</button>
                                        <button class="btn btn-sm btn-info flex-grow-1" onclick="App.Admin.updateStatus('${o.id}', 'On the Way')">${App.I18n.t('btn_ship')}</button>
                                        <button class="btn btn-sm btn-success flex-grow-1" onclick="App.Admin.updateStatus('${o.id}', 'Completed')">${App.I18n.t('btn_complete')}</button>
                                        <button class="btn btn-sm btn-outline-danger" onclick="App.Admin.updateStatus('${o.id}', 'Cancelled')"><i class="bi bi-x-lg"></i></button>
                                        <button class="btn btn-sm btn-dark" onclick="App.Admin.printReceipt('${o.id}', '${o.name.replace(/'/g, "\\'")}', '${o.date}')"><i class="bi bi-printer"></i></button>
                                    </div>
                                </div>`;
                            }).join('');
                        }
                    }

                    // Render Reservations
                    const resList = document.getElementById('admin-reservations-list');
                    if(resList) {
                        if(res.reservations.length > 0) {
                             resList.innerHTML = res.reservations.map(r => `<div class="alert alert-info py-2 small mb-2">${r.date} @ ${r.time} - ${r.name} (${r.guests} ppl)</div>`).join('');
                        } else {
                             resList.innerHTML = `<p class="text-muted small">${App.I18n.t('admin_no_res')}</p>`;
                        }
                    }

                    // --- RENDER ANALYTICS ---
                    if(res.analytics) {
                        App.Admin.renderCharts(res.analytics);
                    }

                    // Restart Polling
                    if(App.State.adminInterval) clearInterval(App.State.adminInterval);
                    App.State.adminInterval = setInterval(App.Admin.fetchDashboard, 30000); 
                } else alert(res.message);
            });
        },

        updateStatus: (id, st) => {
            fetch(API_URL, {method:'POST', body:JSON.stringify({action:'updateStatus', data:{password:App.State.adminPw, orderId:id, newStatus:st}})})
            .then(r=>r.json()).then(res=>{ if(res.status==='success') App.Admin.fetchDashboard(); });
        },

        toggleStore: () => {
             if(!App.State.adminPw) { alert("Please login"); App.Admin.openLogin(); return; }
             const statusEl = document.getElementById('admin-store-status');
             const cardEl = statusEl.closest('.card');
             const isCurrentlyClosed = statusEl.classList.contains('text-danger');
             const newState = !isCurrentlyClosed; 
             const originalClass = statusEl.className;

             // Optimistic Update
             if (newState === true) { statusEl.innerText = App.I18n.t('status_closed'); statusEl.className = "h3 fw-bold text-danger"; } 
             else { statusEl.innerText = App.I18n.t('status_open'); statusEl.className = "h3 fw-bold text-success"; }
             cardEl.style.pointerEvents = "none"; 

             fetch(API_URL, { method: 'POST', body: JSON.stringify({ action: 'toggleStore', data: { password: App.State.adminPw, state: newState } }) })
             .then(r => r.json()).then(res => { 
                 cardEl.style.pointerEvents = "all";
                 if(res.status === 'success') {
                     // Check actual server state
                     const isStoreActuallyOpen = !newState;
                     const floatBadge = document.getElementById('store-float-badge');
                     const storeBanner = document.getElementById('store-closed-banner');
                     if (!isStoreActuallyOpen) { 
                         if(floatBadge) floatBadge.classList.add('active'); 
                         if(storeBanner) storeBanner.style.display = 'block'; 
                     } else { 
                         if(floatBadge) floatBadge.classList.remove('active'); 
                         if(storeBanner) storeBanner.style.display = 'none'; 
                     }
                     App.Admin.fetchDashboard();
                 } else {
                     alert("Server Error"); statusEl.className = originalClass; 
                 }
             }).catch(e => { cardEl.style.pointerEvents = "all"; alert("Connection Failed"); statusEl.className = originalClass; });
        },

        printReceipt: (oid, name, date) => {
            const safeId = oid.replace(/[^a-zA-Z0-9-]/g, '');
            const itemsEl = document.getElementById('items-' + safeId);
            const totalEl = document.getElementById('total-' + safeId);
            if(!itemsEl || !totalEl) return alert(App.I18n.t('err_order_read'));
            const itemsText = itemsEl.innerText; 
            const totalText = totalEl.innerText; 
            const formattedItems = itemsText.replace(/,\s(?=\d+x)/g, '<br>'); 

            const html = `<div class="ticket-header"><h3>SUSHI ELITE</h3><p style="font-size:1.2em; font-weight:bold">#${oid}</p><small>${date}</small></div><div class="ticket-body"><p style="font-weight:bold; border-bottom:1px solid #000; padding-bottom:5px;">Customer: ${name}</p><div style="margin-top:10px; font-size:1.1em">${formattedItems}</div></div><div class="ticket-total">TOTAL: ${totalText}</div><div class="ticket-footer"><p>www.sushielite.ma</p><p>*** THANK YOU ***</p></div>`;

            const area = document.getElementById('print-area');
            if(area) {
                area.innerHTML = html;
                window.print();
            }
        }
    },

// 12. ROUTER (Deep Linking Logic)
    Router: {
        init: () => {
            const path = window.location.pathname;
            let view = App.State.routes[path] || 'home';
            const urlParams = new URLSearchParams(window.location.search);
            if(urlParams.get('view')) view = urlParams.get('view');
            App.Router.loadModule(view);
            window.onpopstate = (e) => App.Router.loadModule(e.state ? e.state.view : 'home');
        },

        go: (viewKey) => {
            const path = Object.keys(App.State.routes).find(key => App.State.routes[key] === viewKey);
            if (path) window.history.pushState({view: viewKey}, "", path);
            App.Router.loadModule(viewKey);
        },

        loadModule: (viewKey) => {
            App.State.currentView = viewKey;
            window.scrollTo(0,0);

            // 1. Hide All Modules
            document.querySelectorAll('.module-section').forEach(e => {
                e.classList.remove('active');
                e.style.display = 'none';
            });

            // 2. DEFINE DEEP LINKS (Views that live inside Profile)
            const profileTabs = ['wishlist', 'orders', 'addresses', 'settings'];

            if (profileTabs.includes(viewKey) || viewKey === 'profile') {
                // Auth Check
                if (!App.State.user) {
                    document.getElementById('home-module').classList.add('active');
                    document.getElementById('home-module').style.display = 'block';
                    App.Auth.openModal();
                    return; 
                }

                // Show Profile Module
                const profile = document.getElementById('profile-module');
                profile.style.display = 'block';
                setTimeout(() => profile.classList.add('active'), 10);

                // Auto-Click the correct Tab
                setTimeout(() => {
                    let tabId = '#tab-cart'; // Default
                    if(viewKey === 'wishlist') tabId = '#tab-wish';
                    if(viewKey === 'orders') tabId = '#tab-orders';
                    if(viewKey === 'addresses') tabId = '#tab-address';

                    // Special case for Settings (if you moved it inside profile) or keep as separate
                    if(viewKey === 'settings') {
                         // If settings is a separate module, handle it differently
                         document.getElementById('profile-module').classList.remove('active');
                         document.getElementById('profile-module').style.display = 'none';
                         document.getElementById('settings-module').style.display = 'block';
                         setTimeout(() => document.getElementById('settings-module').classList.add('active'), 10);
                         return;
                    }

                    // Click the tab if button exists
// Show the tab using Bootstrap API (Prevents infinite loop)
const btn = document.querySelector(`[data-bs-target="${tabId}"]`);
if(btn) {
    const tabInstance = bootstrap.Tab.getOrCreateInstance(btn);
    tabInstance.show();
}
                }, 50);

                // Refresh Data
                App.Auth.check();
                if(viewKey === 'wishlist') App.Wishlist.render();
                return;
            }

            // 3. Standard Modules (Home, Cart, Driver, Admin, Reservation, Catalog)
            const targetId = viewKey + '-module';
            const target = document.getElementById(targetId);

            if (target) {
                target.style.display = 'block';
                setTimeout(() => target.classList.add('active'), 10);
            } else {
                // Fallback
                const home = document.getElementById('home-module');
                if(home) { home.style.display = 'block'; home.classList.add('active'); }
            }

            if(viewKey === 'cart') App.Cart.render();
			if(viewKey === 'wishlist') App.Wishlist.render(); // Add this line
        }
    },

    // 13. AUTH
    Auth: {
        openModal: () => new bootstrap.Modal(document.getElementById('authModal')).show(),

        login: () => { 
            const p = App.Utils.el('login-phone').value; 
            const pass = App.Utils.el('login-pass').value; 
            if(!p) return alert('Enter Phone'); 

            fetch(API_URL, {
                method:'POST', 
                body:JSON.stringify({action:'login', data:{phone:p, password:pass}})
            })
            .then(r=>r.json()).then(res=>{ 
                if(res.status==='success') { 
                    // SAVE ROLE TO LOCAL STORAGE
                    App.State.user = {
                        id: res.userId, 
                        name: res.name, 
                        phone: p, 
                        authToken: res.authToken, 
                        role: res.role // <--- Saved here
                    }; 
                    App.Utils.save('se_user', App.State.user); 
                    location.reload(); 
                } else alert(res.message); 
            }); 
        },

        logout: () => { 
            App.UI.confirm(App.I18n.t('logout_title'), App.I18n.t('logout_msg'), () => { 
                localStorage.removeItem('se_user'); 
                location.reload(); 
            }); 
        },

        check: () => { 
            const u = App.State.user; 
            if(u) { 
                App.Utils.el('profile-logged-in').style.display = 'block'; 
                App.Utils.el('profile-logged-out').style.display = 'none'; 
                App.Utils.el('user-name-display').innerText = u.name; 

                const authBtn = App.Utils.el('auth-btn'); 
                if(authBtn) authBtn.innerHTML = '<i class="bi bi-person-check-fill text-success fs-5"></i>'; 

                // --- ROLE BASED UI TOGGLE ---
                const role = (u.role || 'customer').toLowerCase();

                if (role === 'admin') {
                    const btn = document.getElementById('btn-merchant-access');
                    if(btn) btn.classList.remove('d-none');
                }

                if (role === 'driver' || role === 'admin') {
                    const btn = document.getElementById('btn-driver-access');
                    if(btn) btn.classList.remove('d-none');
                }
                // ---------------------------

                App.Profile.renderHistory(); 
                if(App.Wishlist && typeof App.Wishlist.render === 'function') App.Wishlist.render(); 
                App.Profile.renderAddresses(); 
                App.Profile.updatePointsUI(); 

                const addrSelect = document.getElementById('cart-addr-select'); 
                if(addrSelect && (App.State.addresses.home || App.State.addresses.office)) { 
                    addrSelect.innerHTML = `<option value="">${App.I18n.t('select_addr_ph')}</option>`; 
                    if(App.State.addresses.home) addrSelect.innerHTML += `<option value="Home">${App.I18n.t('lbl_home')}: ${typeof App.State.addresses.home === 'string' ? App.State.addresses.home : App.State.addresses.home.full}</option>`; 
                    if(App.State.addresses.office) addrSelect.innerHTML += `<option value="Office">${App.I18n.t('lbl_office')}: ${typeof App.State.addresses.office === 'string' ? App.State.addresses.office : App.State.addresses.office.full}</option>`; 
                } 
            } 
        }
    },

    // 14. PROFILE
    // 14. PROFILE (Fixed: No Duplicates + GPS)
    Profile: {
        toggleMode: (mode) => {
            const input = document.getElementById('addr-street');
            const btn = document.getElementById('btn-gps-action');

            if(mode === 'gps') {
                input.value = ''; 
                input.placeholder = App.I18n.t('ph_street_gps'); 
                input.readOnly = true; 
                btn.classList.remove('d-none');
            } else {
                input.placeholder = App.I18n.t('ph_street_manual');
                input.readOnly = false; 
                btn.classList.add('d-none'); 
            }
        },

        openAddressModal: (addrType = null) => { 
            const modalEl = document.getElementById('addressModal'); 
            const modal = bootstrap.Modal.getOrCreateInstance(modalEl); 

            // Reset Form & Toggle
            document.getElementById('mode-manual').checked = true;
            App.Profile.toggleMode('manual'); 

            const fields = ['addr-name','addr-street','addr-apt','addr-city','addr-zip'];
            fields.forEach(f => document.getElementById(f).value = "");

            if(addrType) { 
                const data = App.State.addresses[addrType.toLowerCase()]; 
                if(data && typeof data === 'object') { 
                    if(document.getElementById('addr-name')) document.getElementById('addr-name').value = data.name || ''; 
                    if(document.getElementById('addr-street')) document.getElementById('addr-street').value = data.street || ''; 
                    if(document.getElementById('addr-apt')) document.getElementById('addr-apt').value = data.apt || ''; 
                    if(document.getElementById('addr-city')) document.getElementById('addr-city').value = data.city || ''; 
                    if(document.getElementById('addr-zip')) document.getElementById('addr-zip').value = data.zip || ''; 
                    if(document.getElementById('addr-type')) document.getElementById('addr-type').value = addrType; 

                    // If address is a Link, auto-switch to GPS mode
                    if(data.street && data.street.includes('http')) {
                        document.getElementById('mode-gps').checked = true;
                        App.Profile.toggleMode('gps');
                    }
                } 
            } 
            modal.show(); 
        },

        getLocation: (btn) => {
            if (!navigator.geolocation) return alert(App.I18n.t('err_geo_not_supported'));

            const originalHtml = btn.innerHTML;
            btn.disabled = true;
            btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span>';

            navigator.geolocation.getCurrentPosition(
                (position) => {
                    const lat = position.coords.latitude;
                    const long = position.coords.longitude;

                    // --- THE FIX: USE THE CLEAN FORMAT ---
                    // This saves: "https://maps.google.com/maps?q=33.5...,-7.5..."
                    const mapLink = `https://maps.google.com/maps?q=${lat},${long}`;
                    // -------------------------------------

                    document.getElementById('addr-street').value = mapLink;
                    // Trigger input event so any listeners know it changed
                    document.getElementById('addr-street').dispatchEvent(new Event('input'));

                    btn.disabled = false;
                    btn.innerHTML = originalHtml;
                    btn.classList.replace('btn-danger', 'btn-success');

                    App.UI.toast(App.I18n.t('msg_location_found'), "success");
                },
                (error) => {
                    console.error("Geo Error:", error);
                    btn.disabled = false;
                    btn.innerHTML = originalHtml;
                    alert(App.I18n.t('err_geo_failed'));
                },
                { enableHighAccuracy: true, timeout: 10000 }
            );
        },

        renderAddresses: () => { 
            const c = document.getElementById('address-list-grid'); 
            if(!c) return; 
            c.innerHTML = ''; 
            const a = App.State.addresses; 
            let html = ''; 
            if(a.home) html += App.Profile.createAddrCard('Home', a.home); 
            if(a.office) html += App.Profile.createAddrCard('Office', a.office); 
            if(!html) html = `<div class="col-12 text-center text-muted py-3">${App.I18n.t('addr_empty')}</div>`; 
            c.innerHTML = html; 
            App.I18n.updateDOM(); 
        },

        createAddrCard: (type, data) => { 
            const display = (typeof data === 'string') ? data : (data.full || `${data.street} ${data.apt}<br>${data.city}`); 
            const labelKey = type === 'Home' ? 'lbl_home' : 'lbl_office'; 

            // Check for Link to show GPS Icon
            const icon = (data.street && data.street.includes('http')) 
                ? `<i class="bi bi-pin-map-fill text-danger"></i> ${App.I18n.t('lbl_gps_pin')}` 
                : '<i class="bi bi-geo-alt-fill"></i> ' + (data.name || type);

            return `<div class="col-md-6"><div class="address-card"><span class="address-tag" data-i18n="${labelKey}">${App.I18n.t(labelKey)}</span><h6 class="fw-bold mb-3">${icon}</h6><p class="small text-muted mb-3 text-truncate">${display}</p><button class="btn btn-sm btn-outline-dark rounded-pill px-3" onclick="App.Profile.openAddressModal('${type}')" data-i18n="btn_edit">Edit</button></div></div>`; 
        },

        saveAddress: () => { 
            if(!App.State.user) return alert(App.I18n.t('err_login_first'));
            const btn = document.getElementById('save-addr-btn'); 
            if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } 

            const getVal = (id) => { const el = document.getElementById(id); return el ? el.value : ""; }; 
            const type = getVal('addr-type'); 

            const addrData = { 
                name: getVal('addr-name'), 
                street: getVal('addr-street'), 
                apt: getVal('addr-apt'), 
                city: getVal('addr-city'), 
                zip: getVal('addr-zip'), 
                country: getVal('addr-country'), 
                full: `${getVal('addr-street')} ${getVal('addr-apt')}, ${getVal('addr-city')}` 
            }; 

            if(!addrData.street) { 
                if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } 
                return alert('Enter Address'); 
            } 

            fetch(API_URL, {
                method:'POST', 
                body:JSON.stringify({ 
                    action: 'updateAddress', 
                    data: { 
                        userId: App.State.user.id, 
                        authToken: App.State.user.authToken, 
                        type: type, 
                        addressJson: JSON.stringify(addrData) 
                    } 
                })
            })
            .then(r=>r.json())
            .then(res=>{ 
                if(res.status==='success') { 
                    if(type==='Home') App.State.addresses.home = addrData; 
                    else App.State.addresses.office = addrData; 
                    App.Profile.renderAddresses(); 
                    bootstrap.Modal.getInstance(document.getElementById('addressModal')).hide(); 
                    App.UI.toast(App.I18n.t('msg_addr_saved')); 
                } else { alert("Save failed: " + res.message); } 
                if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } 
            })
            .catch(e => { alert("Error saving"); if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_addr'); } }); 
        },

        saveSettings: () => { 
            if(!App.State.user) return; 
            const btn = document.getElementById('save-settings-btn'); 
            if(btn) { btn.disabled = true; btn.innerText = App.I18n.t('btn_saving'); } 
            const n = document.getElementById('setting-name').value; 
            const e = document.getElementById('setting-email').value; 
            const p = document.getElementById('setting-phone').value; 
            fetch(API_URL, {method:'POST', body:JSON.stringify({ action: 'updateUser', data: { userId: App.State.user.id, authToken: App.State.user.authToken, name: n, email: e, phone: p } })})
            .then(r=>r.json())
            .then(res=>{ 
                if(res.status==='success') App.UI.toast(App.I18n.t('msg_settings_saved')); 
                if(btn) { btn.disabled = false; btn.innerText = App.I18n.t('btn_save_changes'); } 
            }); 
        },

        renderHistory: () => { 
            const list = document.getElementById('order-history-list'); 
            if(!list) return; 

            if(App.State.history.length === 0) { 
                list.innerHTML = `<p class="text-muted small py-2">${App.I18n.t('history_empty')}</p>`; 
                return; 
            } 

            list.innerHTML = ''; 

            App.State.history.forEach(o => { 
                const displayTotal = App.Utils.fmt(parseFloat(o.total)) || "0.00 DH"; 
                let thumbsHtml = ''; 

                try { 
                    const items = JSON.parse(o.items); 
                    if(items && items.length) { 
                        thumbsHtml = items.slice(0, 3).map(item => { 
                            var img = IMG_FALLBACK; 
                            if (typeof item === 'object' && item.image) { img = item.image; } 
                            else {
                                let searchStr = (typeof item === 'string') ? item : (item.title ? (item.title.en || item.title) : '');
                                for (var k = 0; k < App.State.catalog.length; k++) { 
                                    var prod = App.State.catalog[k]; 
                                    if(typeof item === 'object' && item.id && String(item.id) === String(prod.id)) { img = prod.image; break; }
                                    if (JSON.stringify(prod.title).includes(searchStr)) { img = prod.image; break; } 
                                }
                            }
                            return `<img src="${App.Utils.optimizeImg(img)}" class="order-thumb-img"/>`; 
                        }).join(''); 
                    } 
                } catch(e) { console.error("History Render Error", e); } 

                const statusClass = (o.status === 'Completed' || o.status === 'Sent' || o.status === 'Delivered') ? 'status-pill-completed' : 'status-pill-processing'; 

                list.innerHTML += `<div class="order-card-modern"><div class="d-flex justify-content-between mb-3"><span class="fw-bold text-dark">#${o.id}</span><span class="text-muted small">${new Date(o.date).toLocaleDateString()}</span></div><div class="order-thumbs d-flex gap-2 mb-3">${thumbsHtml}</div><div class="d-flex justify-content-between align-items-center mb-2"><span class="text-muted">${App.I18n.t('lbl_status')}</span><span class="${statusClass}">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><div class="d-flex justify-content-between align-items-center mb-3"><span class="text-muted">${App.I18n.t('lbl_total')}</span><span class="fw-bold fs-5">${displayTotal}</span></div><div class="d-flex gap-2"><button class="btn btn-primary flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_track')}</button><button class="btn btn-light flex-grow-1 rounded-pill" onclick="App.Profile.showOrderDetail('${o.id}')">${App.I18n.t('btn_details')}</button><button class="btn btn-outline-primary flex-grow-1 rounded-pill" onclick="App.Cart.reorder('${o.items.replace(/"/g, '&quot;')}')"><i class="bi bi-arrow-repeat"></i> ${App.I18n.t('btn_reorder')}</button></div></div>`; 
            }); 
        },

        showOrderDetail: (id) => { 
            const o = App.State.history.find(x => x.id === id); if(!o) return; 
            let itemsHtml = '<p class="text-muted">No item details.</p>'; 
            try { 
                const items = JSON.parse(o.items); 
                if(items && items.length) { 
                    itemsHtml = `<div class="bg-light p-3 rounded mb-3">` + items.map(i => { 
                        let title = "", qty = 1, img = IMG_FALLBACK, unitPrice = 0, pid = null;
                        if (typeof i === 'object') { qty = i.qty; title = App.Utils.getLocalizedText(i.title); img = i.image || IMG_FALLBACK; unitPrice = i.price; pid=i.id; } 
                        else { title = String(i); } 
                        const subtotal = unitPrice * qty; 
                        const displayPrice = unitPrice > 0 ? App.Utils.fmt(subtotal) : ''; 
                        const reviewBtn = (o.status === 'Completed' && pid) ? `<button class="btn btn-link btn-sm text-decoration-none p-0 ms-2" onclick="App.UI.openReviewModal('${pid}')"><small>★ ${App.I18n.t('btn_write_review')}</small></button>` : '';
                        return `<div class="order-detail-row"><img src="${App.Utils.optimizeImg(img)}" class="od-img"/><div><div class="fw-bold small">${qty}x ${title}</div><div class="text-primary small fw-bold">${displayPrice} ${reviewBtn}</div></div></div>`; 
                    }).join('') + `</div>`; 
                } 
            } catch(e) {} 
            let totalVal = parseFloat(o.total) || 0; 
            const statuses = ['Pending', 'Preparing', 'On the Way', 'Delivered']; 
            let currentStep = statuses.indexOf(o.status); if(o.status === 'Completed') currentStep = 3; if(currentStep === -1) currentStep = 0; 
            const timelineHtml = `<div class="timeline">` + statuses.map((s, idx) => { const isActive = idx <= currentStep ? 'active' : ''; const statusKey = 'status_' + s.toLowerCase().replace(/\s/g,'_'); return `<div class="timeline-item ${isActive}"><span class="small ${isActive ? 'fw-bold text-success' : 'text-muted'}">${App.I18n.t(statusKey) || s}</span></div>`; }).join('') + `</div>`; 
            const html = `<div class="p-3"><div class="d-flex justify-content-between align-items-center mb-3"><h5 class="m-0 fw-bold">#${o.id}</h5><span class="badge bg-primary">${App.I18n.t('status_' + o.status.toLowerCase()) || o.status}</span></div><h6 class="small fw-bold text-muted mb-2 text-uppercase">${App.I18n.t('lbl_timeline')}</h6>${timelineHtml}${itemsHtml}<div class="d-flex justify-content-between fw-bold border-top pt-3"><span>${App.I18n.t('total_caps')}</span><span class="text-primary">${App.Utils.fmt(totalVal)}</span></div><button class="btn btn-outline-dark w-100 rounded-pill mt-4" data-bs-dismiss="modal">${App.I18n.t('btn_close')}</button></div>`; 
            document.getElementById('order-detail-body').innerHTML = html; 
            new bootstrap.Modal(document.getElementById('orderDetailModal')).show(); 
        },

        updatePointsUI: () => { 
            const el = document.querySelector('.profile-info .sub-link'); 
            if(el && App.State.user) { el.innerHTML = `<span class="points-badge"><i class="bi bi-star-fill me-1"></i> ${App.State.user.points} ${App.I18n.t('lbl_pts')}</span>`; } 
        }
    },

	// 19. DRIVER MODE
    Driver: {
        pin: "2024",
        interval: null,

        openLogin: () => {
            const modal = document.getElementById('driverLoginModal');
            if(modal) new bootstrap.Modal(modal).show();
        },

        login: () => {
            const input = document.getElementById('driver-pin').value;
            // TRANSLATED ALERT
            if(!input) return alert(App.I18n.t('err_enter_pin'));

            const btn = document.querySelector('#driverLoginModal button');
            const originalText = btn.innerText;
            // TRANSLATED BUTTON TEXT
            btn.innerText = App.I18n.t('btn_checking');
            btn.disabled = true;

            fetch(API_URL, {
                method: 'POST',
                body: JSON.stringify({ action: 'driverLogin', data: { pin: input } })
            })
            .then(r => r.json())
            .then(res => {
                btn.innerText = originalText;
                btn.disabled = false;
                if(res.status === 'success') {
                    App.State.adminPw = input; 
                    const el = document.getElementById('driverLoginModal');
                    const modal = bootstrap.Modal.getInstance(el);
                    if(modal) modal.hide();

                    App.Driver.fetchOrders();
                    App.Router.go('driver');

                    if(App.Driver.interval) clearInterval(App.Driver.interval);
                    App.Driver.interval = setInterval(App.Driver.fetchOrders, 15000);
                } else {
                    // TRANSLATED ERROR
                    alert("❌ " + App.I18n.t('err_wrong_pin'));
                }
            })
            .catch(e => {
                // TRANSLATED ERROR
                alert(App.I18n.t('err_conn_failed'));
                btn.innerText = originalText;
                btn.disabled = false;
            });
        },

        fetchOrders: () => {
            if(!App.State.adminPw) {
                if(App.Driver.interval) { clearInterval(App.Driver.interval); App.Driver.interval = null; }
                return; 
            }
            fetch(API_URL + '?action=getAdminDashboard&pw=' + App.State.adminPw).then(r=>r.json()).then(res => {
                if(res.status !== 'success') return;
                const list = document.getElementById('driver-orders-list');
                if(!list) return;

                const activeOrders = res.orders.filter(o => o.status === 'Preparing' || o.status === 'On the Way');

                if(activeOrders.length === 0) {
                    // TRANSLATED EMPTY STATE
                    list.innerHTML = `<div class="text-center text-muted mt-5"><h5>${App.I18n.t('msg_no_deliveries')}</h5><p>${App.I18n.t('msg_wait_kitchen')}</p></div>`;
                    return;
                }

                list.innerHTML = activeOrders.map(o => {
                    let mapLink = `http://googleusercontent.com/maps.google.com/maps?q=${encodeURIComponent(o.address + " Morocco")}`;
                    let addrDisplay = o.address;

                    if (o.address.includes("http")) {
                        const urlMatch = o.address.match(/(https?:\/\/[^\s]+)/g);
                        if(urlMatch) mapLink = urlMatch[0];
                        mapLink = mapLink.replace("http://googleusercontent.com/", "https://");
                        // TRANSLATED LABEL
                        addrDisplay = `📍 ${App.I18n.t('lbl_gps_location')}`;
                    }

                    const waLink = `https://wa.me/${o.phone}`;
                    const statusKey = 'status_' + o.status.toLowerCase().replace(/\s/g,'');
                    const translatedStatus = (App.I18n && App.I18n.t(statusKey)) ? App.I18n.t(statusKey) : o.status;

                    return `
                    <div class="card border-0 shadow-sm mb-3">
                        <div class="card-body">
                            <div class="d-flex justify-content-between mb-2">
                                <span class="badge bg-warning text-dark">#${o.id}</span>
                                <span class="fw-bold">${translatedStatus}</span>
                            </div>
                            <h5 class="fw-bold mb-1">${o.name}</h5>
                            <a href="${mapLink}" target="_blank" class="btn btn-light w-100 text-start text-truncate mb-3 border">
                                <i class="bi bi-geo-alt-fill text-danger"></i> ${addrDisplay}
                            </a>
                            <div class="d-grid gap-2">
                                <a href="${waLink}" target="_blank" class="btn btn-outline-success fw-bold"><i class="bi bi-whatsapp"></i> ${App.I18n.t('btn_call_wa')}</a>
                                <button class="btn btn-dark fw-bold py-2 mt-2" onclick="App.Admin.updateStatus('${o.id}', 'Delivered')">✅ ${App.I18n.t('btn_mark_delivered')}</button>
                            </div>
                        </div>
                    </div>`;
                }).join('');
            });
        }
    },

    // 17. SOCIAL & ENGAGEMENT (Phase 9)
    Social: {
        init: () => {
            setTimeout(App.Social.showNotification, 10000);
            setInterval(App.Social.showNotification, 45000);
        },
        shareReferral: () => {
            if(!App.State.user) return App.Auth.openModal();
            const code = App.State.user.referralCode || App.State.user.id.substring(0,6).toUpperCase(); 
            const text = `${App.I18n.t('msg_share_ref')} *${code}* %0A ${window.location.href}`;
            window.open(`https://wa.me/?text=${text}`, '_blank');
        },
        showNotification: () => {
            const names = ['Ahmed', 'Sara', 'Karim', 'Salma', 'Omar', 'Yasmine', 'Fatima', 'Mehdi'];
			const cities = ['Maarif', 'Bourgogne', 'California', 'Sidi Maarouf', 'Hay Hassani', 'Derb Omar'];
            //const cities = ['Maarif', 'Bourgogne', 'California', 'Sidi Maarouf', 'Hay Hassani', 'Derb Omar', 'Aïn Chock', 'Anfa', 'Hassani', 'Ben M'Sick', 'Lissasfa', 'Hay El Hana', 'Oasis', 'Racine', 'El Hank', 'El Massira', 'Hay Al Mohammadi', 'Oulfa', 'Derb Sultan', 'Benjdid', 'Sidi Othmane', 'Hay El Fath', 'Mers Sultan', 'Hay El Fida', 'Gauthier', 'Derb Ghallef', 'Hay Al Amal', 'Sidi Othmane', 'Oulfa', 'Hay Mohammadi', 'Bourgogne', 'Anfa', 'Hay Al Amal', 'El Fida', 'Hay El Fath', 'Derb Ghallef', 'Ben M'Sick', 'Oasis', 'Habbous', 'La Ville Verte', 'Sidi Bernoussi', 'Hay El Fida', 'Oulfa', 'Hay Hassani', 'El Hank', 'Hay Al Amal', 'Derb Sultan', 'Bourgogne', 'Maarif'];
            const items = App.State.catalog.length > 0 ? App.State.catalog : [{title: {en: "Sushi Set"}, image: ""}];

            const rName = names[Math.floor(Math.random() * names.length)];
