            const msg = `<b>${rName}</b> (${rCity}) ${App.I18n.t('txt_social_proof')} <br/> <span class="text-primary">${rTitle}</span>`;

            const toast = document.createElement('div');
            toast.className = 'custom-toast border-success social-proof-toast';
