            const container = document.getElementById('toast-container');
            if(container) {
                container.appendChild(toast);
                setTimeout(() => { toast.style.opacity = '0'; setTimeout(()=>toast.remove(), 300); }, 5000);
            }
        }
    },
    // 20. PWA
    // 20. PWA (Smart Notification)
    PWA: {
        deferredPrompt: null,
        init: () => {
            // 1. Generate Manifest
            const manifest = {
                "name": "SushiElite",
                "short_name": "SushiElite",
                "start_url": window.location.href,
                "display": "standalone",
                "background_color": "#ffffff",
                "theme_color": "#ce1212",
                "icons": [
                    { "src": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png", "sizes": "192x192", "type": "image/png" },
                    { "src": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png", "sizes": "512x512", "type": "image/png" }
                ]
            };
            const link = document.createElement('link');
            link.rel = 'manifest';
            link.href = 'data:application/manifest+json;base64,' + btoa(JSON.stringify(manifest));
            document.head.appendChild(link);

            // 2. Listen for Install Event
            window.addEventListener('beforeinstallprompt', (e) => {
                e.preventDefault();
                App.PWA.deferredPrompt = e;

                // CHECK: If user dismissed it previously (LocalStorage), do not show
                if (!localStorage.getItem('se_pwa_dismissed')) {

                    // SMART CHECK: Wait until no other notifications are on screen
                    const checkAndShow = () => {
                        const toasts = document.getElementById('toast-container');
                        // If toast container is empty, we are clear to show
                        if (toasts && toasts.children.length === 0) {
                            document.getElementById('install-prompt').classList.add('active');
                        } else {
                            // Busy? Wait 5 seconds and try again
                            setTimeout(checkAndShow, 5000);
                        }
                    };

                    // Start checking after initial 5s delay
                    setTimeout(checkAndShow, 5000);
                }
            });

            // 3. Handle App Installed
            window.addEventListener('appinstalled', () => {
                App.PWA.deferredPrompt = null;
                document.getElementById('install-prompt').classList.remove('active');
                localStorage.setItem('se_pwa_dismissed', 'true'); // Never show again
                App.UI.toast("App Installed Successfully!", "success");
            });
        },
        install: async () => {
            const promptEvent = App.PWA.deferredPrompt;
            if (!promptEvent) return;
            promptEvent.prompt();
            const { outcome } = await promptEvent.userChoice;
            if (outcome === 'accepted') {
                console.log('User accepted');
            }
            App.PWA.deferredPrompt = null;
            document.getElementById('install-prompt').classList.remove('active');
        }
    },
    // 21. SEO
    SEO: {
        init: () => {
            const script = document.getElementById('json-ld-store');
            const data = {
                "@context": "https://schema.org",
                "@type": "Restaurant",
                "name": "SushiElite",
                "image": "https://cdn-icons-png.flaticon.com/512/2252/2252076.png",
                "telephone": App.Config.waNumber,
                "priceRange": "$$",
                "address": {
                    "@type": "PostalAddress",
                    "addressCountry": "MA"
                }
            };
            script.textContent = JSON.stringify(data);
        },
        setProduct: (p) => {
            const script = document.getElementById('json-ld-store');
            const data = {
                "@context": "https://schema.org",
                "@type": "Product",
                "name": App.Utils.getLocalizedText(p.title),
                "image": p.image || IMG_FALLBACK,
                "description": App.Utils.getLocalizedText(p.desc).replace(/<[^>]*>?/gm, ''),
                "offers": {
                    "@type": "Offer",
                    "priceCurrency": "MAD",
                    "price": p.price_MAD,
                    "availability": p.stock > 0 ? "https://schema.org/InStock" : "https://schema.org/OutOfStock"
                }
            };
            script.textContent = JSON.stringify(data);
        }
    }
};

document.addEventListener('DOMContentLoaded', () => {
    if (typeof AOS !== 'undefined') { AOS.init(); }

    // 1. Core Logic Init
    App.Catalog.searchDebounced = App.Utils.debounce(App.Catalog._searchImpl, 300);
    App.State.cart = App.Utils.load('se_cart') || [];
    App.State.wishlist = App.Utils.load('se_wish') || [];
    App.State.recent = App.Utils.load('se_recent') || [];
    App.State.user = App.Utils.load('se_user');

    // 2. Offline Listeners
    window.addEventListener('offline', () => { App.UI.toast("You are offline. Changes saved locally.", "warning"); });
    window.addEventListener('online', () => { App.UI.toast("Back online!", "success"); App.API.init(); });

// --- NEW: START STATUS POLLING (Every 60 Seconds) ---
    setInterval(() => {
        if(App.State.user) {
            // true = polling mode (no loading spinner)
            App.API.fetchUserData(true); 
        }
    }, 60000);

    // 3. Welcome / Init Logic
    if (!localStorage.getItem('se_setup_done')) {
        const browserLang = navigator.language.slice(0,2);
        if (['en', 'fr', 'ar'].includes(browserLang)) {
            App.State.tempLang = browserLang;
            setTimeout(() => {
                 ['en','fr','ar'].forEach(l => document.getElementById('wel-lang-'+l)?.classList.remove('selected'));
                 document.getElementById('wel-lang-'+browserLang)?.classList.add('selected');
                 const btn = document.getElementById('btn-welcome-start');
                 if(btn && App.State.translations['btn_start_ordering']) btn.innerText = App.State.translations['btn_start_ordering'][browserLang];
            }, 500);
        }
        const welcomeModal = new bootstrap.Modal(document.getElementById('welcomeModal'));
        welcomeModal.show();
    } else {
        App.State.lang = localStorage.getItem('se_lang') || 'en';
        const storedCurr = localStorage.getItem('se_curr');
        if(storedCurr) { App.State.currency = storedCurr; }
        if(App.State.wishlist) App.Utils.el('nav-wish-count').innerText = App.State.wishlist.length;
        const storedTheme = localStorage.getItem('se_theme');
        if(storedTheme) { document.body.setAttribute('data-theme', storedTheme); if(document.getElementById('theme-toggle')) document.getElementById('theme-toggle').checked = (storedTheme === 'dark'); }
        document.documentElement.setAttribute('dir', App.State.lang === 'ar' ? 'rtl' : 'ltr');
        App.UI.updateIcons();
    }

    //App.Router.go('home');
	App.Router.init(); // <--- ADD THIS (It auto-detects if home or cart)
    App.API.init();
    App.Auth.check();
    App.Cart.render();

	App.UI.hideLoader();

    // Init SEO & PWA & Social
    if(App.PWA) App.PWA.init();
    if(App.SEO) App.SEO.init();
    if(App.Social) App.Social.init();

    // Phase 12: Abandoned Cart Check (Refined)
    if (App.State.cart.length > 0) {
        // CHECK: Only show once per browser session (SessionStorage)
        if (!sessionStorage.getItem('se_welcome_shown')) {
            const lastSaved = localStorage.getItem('se_last_save');
            const now = Date.now();

            // If cart exists and last save was > 1 hour ago (3600000 ms)
            if (lastSaved && (now - parseInt(lastSaved)) > 3600000) {
                const toast = document.createElement('div');
                toast.className = 'custom-toast border-primary';
                toast.id = 'welcome-toast'; // ID helps PWA logic know it's there
                toast.innerHTML = `
                    <div>
                        <strong class="d-block mb-1">SushiElite</strong>
                        <span class="small">${App.I18n.t('msg_welcome_back')}</span>
                    </div>
                    <div class="d-flex align-items-center gap-2">
                        <button class="btn btn-sm btn-primary rounded-pill" onclick="App.Router.go('cart'); this.closest('.custom-toast').remove()">${App.I18n.t('btn_resume_order')}</button>
                        <button class="btn-close" onclick="this.closest('.custom-toast').remove()"></button>
                    </div>
                `;
                document.getElementById('toast-container').appendChild(toast);

                // Mark as shown for this session so it doesn't appear on refresh
                sessionStorage.setItem('se_welcome_shown', 'true');
            }
        }
    }
    // Update save time whenever cart changes
    const originalSave = App.Utils.save;
    App.Utils.save = function(key, val) {
        if(key === 'se_cart') localStorage.setItem('se_last_save', Date.now());
        originalSave(key, val);
    };

    // 4. SAFE SCRIPT LOADER (Fixes Calendar & Confetti)
    const loadScript = (src, callback) => {
        const s = document.createElement('script');
        s.src = src;
        s.onload = callback;
        document.head.appendChild(s);
    };

    // Load Confetti
    loadScript('https://cdn.jsdelivr.net/npm/canvas-confetti@1.6.0/dist/confetti.browser.min.js', null);

    // Load Flatpickr Chain
    loadScript('https://cdn.jsdelivr.net/npm/flatpickr', () => {
        loadScript('https://npmcdn.com/flatpickr/dist/l10n/ar.js', () => {
            loadScript('https://npmcdn.com/flatpickr/dist/l10n/fr.js', () => {

                // Initialize Calendar
                const currentLang = App.State.lang;
                const localeMap = { 'ar': 'ar', 'fr': 'fr', 'en': 'default' };

                flatpickr("#res-date", { 
                    minDate: "today", 
                    dateFormat: "Y-m-d",
                    locale: localeMap[currentLang] || 'default',
                    disableMobile: false, 
                    allowInput: false,    
                    onOpen: function(selectedDates, dateStr, instance) {
                        document.activeElement.blur();
                    }
                });

            });
        });
    });
});
//
